window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-91"]=[{"id":"set2-Nv_SGF0e","fingerprint":"10ecbfbe688cb02b","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este caracteristica definitorie a unei leziuni carioase de adâncime medie?","options":[{"id":"A","text":"Prezența unor bogate depozite de dentină alterată de culoare gălbuie."},{"id":"B","text":"Localizarea exclusivă pe suprafețele libere ale dinților, expuse autocurățirii."},{"id":"C","text":"Afectarea smalțului și a unei porțiuni mici din dentină."},{"id":"D","text":"Interpunerea unui strat de dentină dură sănătoasă de 2-3 mm între procesul carios și camera pulpară."},{"id":"E","text":"Extinderea leziunii în imediata vecinătate a camerei pulpare."}],"correct":["D"],"pages":[38],"source":"set-2"},{"id":"set2-BHfF10MF","fingerprint":"53f0723a4f8c6d4f","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele afirmații caracterizează leziunile carioase cu evoluție rapidă (carii umede)?","options":[{"id":"A","text":"Prezintă o culoare gălbuie a dentinei alterate."},{"id":"B","text":"Sunt caracteristice vârstelor tinere."},{"id":"C","text":"Dentina alterată are o consistență moale."},{"id":"D","text":"Sunt specifice vârstelor înaintate."},{"id":"E","text":"Au aspectul unor pete brune-maronii ale smalțului."}],"correct":["A","B","C"],"pages":[38],"source":"set-2"},{"id":"set2-5QFgz136","fingerprint":"13bad5c202ad8a2a","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Referitor la clasificarea cariilor după momentul apariției și legătura cu o restaurare, care dintre următoarele definiții sunt corecte?","options":[{"id":"A","text":"Caria secundară marginală este localizată la interfața preparație/restaurare."},{"id":"B","text":"Cariile primare apar pe un dinte clinic sănătos, indemn de carie."},{"id":"C","text":"Cariile secundare sunt întotdeauna leziuni cu evoluție lentă (uscate)."},{"id":"D","text":"Recidiva de carie reprezintă o leziune carioasă situată sub materialul restaurator."},{"id":"E","text":"Cariile primare sunt leziuni necavitare cu demineralizare reversibilă."}],"correct":["A","B","D"],"pages":[38],"source":"set-2"},{"id":"set2-1O95iuC0","fingerprint":"1e48f79c3b680b1a","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce aspect clinic specific prezintă leziunile carioase staționare, oprite din evoluție?","options":[{"id":"A","text":"Dentina alterată de consistență fermă și culoare brună-cafenie."},{"id":"B","text":"O pierdere minimă de țesut dentar în zona fisurilor sau șanțurilor."},{"id":"C","text":"O leziune cavitară extinsă în imediata vecinătate a camerei pulpare."},{"id":"D","text":"Dentina alterată de consistență moale și culoare gălbuie."},{"id":"E","text":"Pete brune-maronii ale smalțului, cu o suprafață ușor rugoasă."}],"correct":["E"],"pages":[38],"source":"set-2"},{"id":"set2-G6h2XOsn","fingerprint":"86455b3c467517e9","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este principala caracteristică a leziunilor necavitare în clasificarea după stadiul de demineralizare?","options":[{"id":"A","text":"Se detectează doar prin examene paraclinice."},{"id":"B","text":"Sunt întotdeauna localizate la nivelul coletului."},{"id":"C","text":"Sunt oprite din evoluție și au culoare brună-maronie."},{"id":"D","text":"Demineralizarea este reversibilă."},{"id":"E","text":"Afectează smalțul și o porțiune mare din dentină."}],"correct":["D"],"pages":[38],"source":"set-2"},{"id":"set2-YaGOupzK","fingerprint":"ddad23d9c870ce79","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele elemente fac parte din procesul de diagnostic odontal?","options":[{"id":"A","text":"Notarea cariilor simple cu abrevierea 'O'."},{"id":"B","text":"Notarea resturilor radiculare cu abrevierea 'RR'."},{"id":"C","text":"Realizarea unui examen clinic după igienizarea profesională a arcadelor dentare."},{"id":"D","text":"Marcarea grafică în foaia de observație a dinților absenți."},{"id":"E","text":"Utilizarea unor examene paraclinice în anumite situații."}],"correct":["C","D","E"],"pages":[38],"source":"set-2"},{"id":"set2-kFmd73zf","fingerprint":"ad510fc390c47489","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este diferența fundamentală între detecție și diagnostic în contextul stomatologic?","options":[{"id":"A","text":"Detecția este arta de a identifica o boală, în timp ce diagnosticul este metoda obiectivă de determinare a prezenței semnelor."},{"id":"B","text":"Detecția este o metodă obiectivă de determinare a prezenței semnelor și simptomelor, iar diagnosticul este arta de a identifica boala pe baza acestora."},{"id":"C","text":"Detecția se aplică doar leziunilor incipiente, în timp ce diagnosticul se aplică leziunilor cavitare."},{"id":"D","text":"Detecția se aplică doar leziunilor incipiente, în timp ce diagnosticul se aplică leziunilor cavitare."},{"id":"E","text":"Ambele concepte, detecția și diagnosticul, se referă exclusiv la alegerea unei modalități de tratament."}],"correct":["B"],"pages":[39],"source":"set-2"},{"id":"set2-wR31E8UD","fingerprint":"e345641cc2777c95","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele sunt caracteristici ale unui test de detecție ideal?","options":[{"id":"A","text":"Să furnizeze date simple, certe și direct corelabile cu evoluția biologică."},{"id":"B","text":"Să fie noninvaziv, realist și obiectiv."},{"id":"C","text":"Să necesite o dotare tehnică deosebită pentru a asigura precizia."},{"id":"D","text":"Să fie lent și nespecific."},{"id":"E","text":"Să fie rapid, senzitiv și specific."}],"correct":["A","B","E"],"pages":[39],"source":"set-2"},{"id":"set2-twI9Hr-6","fingerprint":"8d2a3cdd49fb7502","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Conform clasificării prezentate, care sunt principalele categorii de metode de detecție a leziunilor dentare?","options":[{"id":"A","text":"Metode profilactice, fisurotomia și aer abraziunea."},{"id":"B","text":"Metode clinice directe, metode clinice indirecte și metode exploratorii."},{"id":"C","text":"Metode profilactice, metode invazive și metode noninvazive."},{"id":"D","text":"Metode vizuale, metode tactile și metode radiologice."},{"id":"E","text":"Metode de detecție a leziunilor incipiente, necavitare și cavitare."}],"correct":["B"],"pages":[39],"source":"set-2"},{"id":"set2-FtP28_D2","fingerprint":"c91ea126eda5649e","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele metode de detecție sunt considerate metode clinice directe?","options":[{"id":"A","text":"Fisurotomia."},{"id":"B","text":"Semnul firului de mătase."},{"id":"C","text":"Tehnici ultrasonice"},{"id":"D","text":"Transiluminarea (diafanoscopia FOTI, DIFOTI)."},{"id":"E","text":"Metoda vizuală cu cameră intraorală."}],"correct":["B","E"],"pages":[39],"source":"set-2"},{"id":"set2-K1lYDOk5","fingerprint":"2fce11e702ed8d5c","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Ce metode fac parte din categoria metodelor clinice indirecte (alternative) de detecție?","options":[{"id":"A","text":"Metoda vizual-tactilă și metoda vizuală cu separare temporară a dinților."},{"id":"B","text":"Detartrajul și periajul profesional."},{"id":"C","text":"Markerii coloranți și tehnicile ultrasonice."},{"id":"D","text":"Aer abraziunea."},{"id":"E","text":"Fluorescența QLF și spectroscopia laser."}],"correct":["C","E"],"pages":[39],"source":"set-2"},{"id":"set2-yr56nj9d","fingerprint":"38737cbcaa38d55b","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este scopul principal al metodelor exploratorii în detecția leziunilor dentare?","options":[{"id":"A","text":"De a facilita îndepărtarea depozitelor de pe suprafețele dentare pentru a ușura detecția."},{"id":"B","text":"De a utiliza markeri coloranți pentru a vizualiza demineralizarea."},{"id":"C","text":"De a identifica leziunile dentare prin intermediul radiografiilor digitale."},{"id":"D","text":"De a furniza date simple, certe și direct corelabile cu evoluția biologică la nivelul structurii investigate."},{"id":"E","text":"De a evalua starea gingiei ca indicator al prezenței leziunilor proximale."}],"correct":["A"],"pages":[39],"source":"set-2"},{"id":"set2-gFU9JG5k","fingerprint":"a0c8f6e5a0e99184","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt localizările tipice pentru leziunile carioase situate în șanțuri și fosete?","options":[{"id":"A","text":"Suprafețele palatinale ale incisivilor centrali și laterali superiori (foramen caecum)."},{"id":"B","text":"Pe fețele proximale ale premolarilor și molarilor."},{"id":"C","text":"Fețele ocluzale ale molarilor și premolarilor."},{"id":"D","text":"Fosetele de pe fețele vestibulare și orale ale molarilor."},{"id":"E","text":"Exclusiv în fosetele de pe suprafețele palatinale ale caninilor superiori."}],"correct":["A","C","D"],"pages":[39],"source":"set-2"},{"id":"set2-kqYjCYBQ","fingerprint":"652a3957aaabc908","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile unei leziuni necavitare?","options":[{"id":"A","text":"Absența demineralizării smalțului."},{"id":"B","text":"O ușoară modificare de transluciditate."},{"id":"C","text":"Prezența unei colorații galben-brune."},{"id":"D","text":"Detectarea ușoară prin palpare cu sonda standard."},{"id":"E","text":"Suprafața dentară este aparent sănătoasă."}],"correct":["A","B","E"],"pages":[40],"source":"set-2"},{"id":"set2-RzJgnxIw","fingerprint":"6e7307971ed0680f","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce aspect clinic indică o leziune de demineralizare avansată cu evoluție rapidă?","options":[{"id":"A","text":"Suprafață de culoare galben-brună."},{"id":"B","text":"Suprafață de culoare albă, dură și lucioasă."},{"id":"C","text":"O ușoară modificare a translucidității."},{"id":"D","text":"Colorație brun-cafenie la deschiderea cavității."},{"id":"E","text":"Suprafață dentară aparent sănătoasă."}],"correct":["B"],"pages":[40],"source":"set-2"},{"id":"set2-On5HOJaX","fingerprint":"a86d10321c68191d","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce tip de leziune carioasă cavitară se caracterizează prin localizarea în zona profundă a dentinei și subminarea parțială a cuspizilor?","options":[{"id":"A","text":"Leziune superficială, microcavitară."},{"id":"B","text":"Leziune cavitară în zona dentinei circumpulpare."},{"id":"C","text":"Leziune profundă."},{"id":"D","text":"Leziune medie."},{"id":"E","text":"Leziune necavitară."}],"correct":["C"],"pages":[40],"source":"set-2"},{"id":"set2-zqWhssa-","fingerprint":"3adac353c00bd455","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"În ce situație clinică este recomandată utilizarea sondei cu bilă în detrimentul sondei standard ascuțite?","options":[{"id":"A","text":"Pentru a verifica integritatea crestei marginale la dinții frontali."},{"id":"B","text":"Pentru diagnosticarea leziunilor necavitare."},{"id":"C","text":"Pentru diagnosticarea cariilor de pe fețele proximale ale molarilor."},{"id":"D","text":"Pentru detectarea cavitației."},{"id":"E","text":"Pentru a evalua leziunile de demineralizare avansată."}],"correct":["D"],"pages":[40],"source":"set-2"},{"id":"set2-ix3AEoad","fingerprint":"505d4349404d729d","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt metodele de diagnostic menționate pentru o carie incipientă situată la nivelul ariei de contact la un molar, unde palparea este imposibilă?","options":[{"id":"A","text":"Palparea cu o sondă standard ascuțită."},{"id":"B","text":"Inspecția vizuală directă a petei albe cretoase."},{"id":"C","text":"Observarea unei papile interdentare edemațiate."},{"id":"D","text":"Examenul radiologic."},{"id":"E","text":"Separarea dentară lentă."}],"correct":["D","E"],"pages":[40],"source":"set-2"},{"id":"set2-HrObs-LK","fingerprint":"f833938d880b31de","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Ce semne clinice caracterizează o leziune carioasă situată sub aria de contact?","options":[{"id":"A","text":"Evoluție rapidă în profunzime și subgingival."},{"id":"B","text":"Interesarea cementului radicular."},{"id":"C","text":"Diagnosticare dificilă, care necesită exclusiv examen radiologic."},{"id":"D","text":"Apariția unei pete albe cretoase la nivelul crestei marginale."},{"id":"E","text":"Papilă interdentară edemațiată și de culoare roșie-violacee."}],"correct":["A","B","E"],"pages":[40],"source":"set-2"},{"id":"set2-6bf0xNBd","fingerprint":"930be5483e08eeb9","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care dintre următoarele reprezintă o localizare specifică a cariilor proximale la nivelul dinților frontali?","options":[{"id":"A","text":"Leziune care interesează cementul radicular."},{"id":"B","text":"Leziune localizată sub aria de contact."},{"id":"C","text":"Leziune medie, situată în dentină, fără subminarea cuspizilor."},{"id":"D","text":"Leziune localizată la nivelul ariei de contact, diagnosticată prin separare dentară."},{"id":"E","text":"Leziune cu evoluție spre unghiul incizal."}],"correct":["E"],"pages":[40],"source":"set-2"},{"id":"set2-Lvr5_wJI","fingerprint":"bcd7a538a64d346c","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce situație clinică este descrisă de o leziune carioasă care subminează creasta marginală a unui molar?","options":[{"id":"A","text":"O carie localizată deasupra ariei de contact."},{"id":"B","text":"O leziune cavitară profundă."},{"id":"C","text":"O carie localizată sub aria de contact."},{"id":"D","text":"O carie incipientă pe mijlocul feței proximale a unui dinte frontal."},{"id":"E","text":"O carie localizată la nivelul ariei de contact."}],"correct":["A"],"pages":[40],"source":"set-2"},{"id":"set2-K9wLfuPt","fingerprint":"9a67f659f8524b57","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt metodele utilizate pentru confirmarea diagnosticului unei leziuni carioase incipiente localizate pe mijlocul feței proximale?","options":[{"id":"A","text":"Separarea dinților cu un separator special pentru a permite palparea suprafeței proximale."},{"id":"B","text":"Utilizarea unei metode de transiluminare pentru a evidenția o zonă de smalț fără transparență."},{"id":"C","text":"Testarea vitalității pulpare pentru a evalua răspunsul la stimuli termici."},{"id":"D","text":"Aplicarea unui revelator de carie pentru a colora dentina afectată."},{"id":"E","text":"Observarea directă a modificării de culoare a crestei marginale."}],"correct":["A","B"],"pages":[41],"source":"set-2"},{"id":"set2-TeEcWANQ","fingerprint":"fc0c05237c5da69c","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Cum se prezintă clinic o leziune carioasă incipientă, necavitară, situată în zona cervicală?","options":[{"id":"A","text":"Ca o suprafață netedă, de culoare maro-deschis sau închis."},{"id":"B","text":"Sub forma unei pete albe, cretoase și mate."},{"id":"C","text":"Printr-o colorație cenușie ce transpare prin stratul de smalț."},{"id":"D","text":"Prin prezența unei cavități cu adâncime mai mică de 0,5 mm."},{"id":"E","text":"Ca o leziune cavitară cu dentină moale la palpare."}],"correct":["B"],"pages":[41],"source":"set-2"},{"id":"set2-rium4Cwl","fingerprint":"503d9d34def99181","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile evolutive ale cariilor cervicale?","options":[{"id":"A","text":"Se pot extinde înconjurând dintele la colet, devenind carii circulare."},{"id":"B","text":"Sunt de obicei asimptomatice, durerea fiind un semn tardiv."},{"id":"C","text":"Sunt limitate strict la coroana anatomică, fără a afecta rădăcina."},{"id":"D","text":"Pot evolua subgingival, ajungând să intereseze și cementul radicular."},{"id":"E","text":"Evoluează inițial în profunzime, afectând rapid dentina, și ulterior în suprafață."}],"correct":["A","D"],"pages":[41],"source":"set-2"},{"id":"set2-ZI_TTbcs","fingerprint":"663b4bab85e06907","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce definește forma cavitară medie a unei leziuni carioase situate pe suprafața radiculară?","options":[{"id":"A","text":"Prezența dentinei necrotice de colorație variabilă, de la gălbui la maro-închis."},{"id":"B","text":"O suprafață netedă, necavitară, de culoare maro-deschis sau închis."},{"id":"C","text":"O adâncime mai mare de 0,5 mm, cu dentina moale la palpare."},{"id":"D","text":"O adâncime mai mică de 0,5 mm, cu suprafața cementului moale și opacă."},{"id":"E","text":"O extindere mai mare în sens vertical decât orizontal."}],"correct":["C"],"pages":[41],"source":"set-2"},{"id":"set2-Eikj4_8e","fingerprint":"d331deb26e498fdd","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care dintre următoarele afirmații descriu corect leziunile carioase active de pe suprafața radiculară?","options":[{"id":"A","text":"Sunt caracterizate prin distrucția stratului de cement și evoluție rapidă pe suprafața dentinei."},{"id":"B","text":"Extinderea acestor leziuni este mai mare în profunzime decât în suprafață."},{"id":"C","text":"Extinderea lor este mai pronunțată în sens vertical decât în sens orizontal."},{"id":"D","text":"Forma necavitară se caracterizează printr-o suprafață rugoasă, alb-cretoasă."},{"id":"E","text":"Forma cavitară profundă prezintă dentină de consistență dură și culoare deschisă."}],"correct":["A"],"pages":[41],"source":"set-2"},{"id":"set2-CXEh_3_G","fingerprint":"47c256af8b5d710c","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este caracteristica specifică a durerii în caria simplă, conform simptomatologiei descrise de pacient?","options":[{"id":"A","text":"Este o durere pulsatilă care iradiază."},{"id":"B","text":"Apare la excitanți termici (rece) și chimici (dulce) și dispare la îndepărtarea excitantului."},{"id":"C","text":"Este o durere surdă, persistentă, care nu cedează la stimuli."},{"id":"D","text":"Apare doar la masticație și indică o leziune a papilei interdentare."},{"id":"E","text":"Este spontană, neprovocată și de intensitate crescută."}],"correct":["B"],"pages":[41],"source":"set-2"},{"id":"set2-awYhwBpe","fingerprint":"57824d6bacc8fdc9","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele semne și simptome pot face parte din tabloul clinic subiectiv al cariei simple?","options":[{"id":"A","text":"Retenție alimentară în cavitate, care determină halenă fetidă."},{"id":"B","text":"Mobilitate dentară progresivă."},{"id":"C","text":"Sângerarea papilei interdentare la masticație sau la periaj."},{"id":"D","text":"Durere spontană, care nu necesită un excitant pentru a fi declanșată."},{"id":"E","text":"Leziuni la nivelul mucoasei labiale, jugale sau linguale."}],"correct":["A","C","E"],"pages":[41],"source":"set-2"},{"id":"set2-tZ3z6Yk5","fingerprint":"bf286b50309c9c5f","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Ce elemente pot fi identificate la inspecție în cadrul examenului clinic obiectiv pentru caria dentară?","options":[{"id":"A","text":"Modificarea de culoare de la alb-cretos la brun-cenușiu."},{"id":"B","text":"Retenția alimentară și halena fetidă."},{"id":"C","text":"Sângerarea papilei interdentare la masticație."},{"id":"D","text":"Durere la aplicarea unui stimul rece."},{"id":"E","text":"Lipsa variabilă de substanță dură dentară, precum smalț, dentină sau cement."}],"correct":["A","E"],"pages":[41],"source":"set-2"},{"id":"set2-ex0VMDyg","fingerprint":"6c30a4be98a9a2ec","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele semne clinice pot fi constatate la palparea unei leziuni carioase simple?","options":[{"id":"A","text":"Sensibilitate la palpare cu sonda și la exereza dentinei necrotice."},{"id":"B","text":"Camera pulpară închisă și fără semne de suferință pulpară."},{"id":"C","text":"Camera pulpară deschisă, cu semne de suferință pulpară."},{"id":"D","text":"Pierderea de substanță dură dentară, evaluabilă în suprafață și profunzime."},{"id":"E","text":"Prezența dentinei necrotice de consistență variabilă."}],"correct":["A","B","D","E"],"pages":[42],"source":"set-2"},{"id":"set2-HjAwJVUl","fingerprint":"4ab5d3d8045f61b3","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Pe baza căror criterii se stabilește diagnosticul pozitiv de carie simplă?","options":[{"id":"A","text":"Teste de sensibilitate pulpară pozitive și percuție negativă."},{"id":"B","text":"Prezența dentinei necrotice și camera pulpară deschisă."},{"id":"C","text":"Modificare de culoare și sensibilitate la palpare pe pereții juxtapulpari."},{"id":"D","text":"Pierdere de substanță dură dentară și camera pulpară închisă."},{"id":"E","text":"Durere provocată care persistă 10-15 minute după îndepărtarea excitantului."}],"correct":["A","C","D"],"pages":[42],"source":"set-2"},{"id":"set2-oOLYt5CR","fingerprint":"5d8a4bdac0e6d164","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Prin ce caracteristică a durerii se diferențiază hiperemia preinflamatorie de caria simplă?","options":[{"id":"A","text":"În antecedente pot exista pusee dureroase."},{"id":"B","text":"Durerea provocată dispare imediat odată cu îndepărtarea excitantului."},{"id":"C","text":"Durerea apare la palparea zonelor afectate sau la masticație."},{"id":"D","text":"Absența completă a durerii, deoarece testele de sensibilitate sunt negative."},{"id":"E","text":"Durerea provocată de excitanți durează 10-15 minute după îndepărtarea acestora."}],"correct":["E"],"pages":[42],"source":"set-2"},{"id":"set2-svfICmP4","fingerprint":"ea56f619f9700d04","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile clinice ale gangrenei pulpare, utilizate în diagnosticul diferențial față de caria simplă?","options":[{"id":"A","text":"Testele de sensibilitate sunt negative."},{"id":"B","text":"Prezintă semne radiologice de afectare a parodonțiului apical."},{"id":"C","text":"Testele de sensibilitate sunt pozitive, dar pulpa prezintă hipoexcitabilitate."},{"id":"D","text":"Durerea provocată persistă un timp îndelungat după îndepărtarea stimulului."},{"id":"E","text":"Procesul carios este profund și camera pulpară este deschisă."}],"correct":["A","E"],"pages":[42],"source":"set-2"},{"id":"set2-ilgZgreO","fingerprint":"6e494bd8e30786fd","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce element de diagnostic diferențial este specific pulpitelor cronice închise în comparație cu caria simplă?","options":[{"id":"A","text":"Prezența semnelor radiologice de afectare a parodonțiului apical."},{"id":"B","text":"Hipoexcitabilitate la testele de sensibilitate comparativ cu dinții omologi sănătoși."},{"id":"C","text":"Testele de sensibilitate sunt complet negative."},{"id":"D","text":"Durerea dispare imediat după îndepărtarea excitantului."},{"id":"E","text":"Lipsa dentinei necrotice."}],"correct":["B"],"pages":[42],"source":"set-2"},{"id":"set2-4YMYe0Of","fingerprint":"b65cc205dcb707f4","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este un criteriu esențial utilizat pentru a diferenția o carie dentară de leziunile necarioase de uzură (atriție, eroziune)?","options":[{"id":"A","text":"Apariția durerii la periaj."},{"id":"B","text":"Prezența modificărilor de culoare."},{"id":"C","text":"Pierderea de substanță dură dentară."},{"id":"D","text":"Lipsa dentinei necrotice în leziunile necarioase."},{"id":"E","text":"Interesarea unui singur dinte."}],"correct":["D"],"pages":[42],"source":"set-2"},{"id":"set2-iV2I7Xq6","fingerprint":"ae5b75d5a8cd6650","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Ce complicații imediate poate determina un proces carios netratat la timp?","options":[{"id":"A","text":"Apariția edentațiilor extinse."},{"id":"B","text":"Inflamații pulpare acute și cronice."},{"id":"C","text":"Gangrena pulpară simplă."},{"id":"D","text":"Extracția dentară."},{"id":"E","text":"Tulburări funcționale și ocluzale."}],"correct":["B","C"],"pages":[42],"source":"set-2"},{"id":"set2-K557VOOc","fingerprint":"ede4d7dd286939eb","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt posibilele complicații ale proceselor carioase care nu beneficiază de tratament la timp?","options":[{"id":"A","text":"Inflamații pulpare acute și cronice."},{"id":"B","text":"Apariția unor focare de infecție la distanță."},{"id":"C","text":"Hiperplazie gingivală."},{"id":"D","text":"Extracția dentară urmată de edentație."},{"id":"E","text":"Parodontită marginală cronică."}],"correct":["A","B","D"],"pages":[43],"source":"set-2"},{"id":"set2-JEEbjhVG","fingerprint":"7d301e5f67e07e1a","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce definește caria secundară marginală?","options":[{"id":"A","text":"O complicație tardivă a gangrenei pulpare, caracterizată prin modificări de culoare ale întregii coroane dentare."},{"id":"B","text":"Un proces carios cu evoluție rapidă care apare imediat după realizarea unei obturații, în primele câteva săptămâni."},{"id":"C","text":"O afecțiune care apare la interfața dintre o restaurare coronară și țesutul dentar, fiind adesea rezultatul unor factori iatrogeni."},{"id":"D","text":"O leziune carioasă primară care apare exclusiv pe suprafețele ocluzale ale dinților vitali."},{"id":"E","text":"O afecțiune dureroasă încă de la debut, care necesită întotdeauna tratament endodontic."}],"correct":["C"],"pages":[43],"source":"set-2"},{"id":"set2-pW9coP2O","fingerprint":"c346db5f5cf10fa2","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele sunt semne clinice subiective pe care le poate acuza un pacient cu carie secundară marginală?","options":[{"id":"A","text":"Dureri provocate de excitanți fizici (rece) sau chimici (dulce), care persistă mult timp după îndepărtarea excitantului."},{"id":"B","text":"Prezența dentinei alterate și a marginilor de smalț modificate de culoare, observate de medic."},{"id":"C","text":"Dureri la masticație în zona laterală, cauzate de fracturarea sau dislocarea restaurării."},{"id":"D","text":"Modificarea de culoare a obturației, vizibilă în special la dinții frontali."},{"id":"E","text":"Retenția de resturi alimentare la marginea restaurării."}],"correct":["C","D","E"],"pages":[43],"source":"set-2"},{"id":"set2-Lmv55U-G","fingerprint":"993aeb3ca5537015","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este semnul clinic obiectiv caracteristic pentru faza de debut a cariei secundare marginale?","options":[{"id":"A","text":"Fracturarea unui perete al cavității și/sau a materialului de restaurare."},{"id":"B","text":"Sensibilitate dureroasă difuză pe care pacientul nu o poate localiza."},{"id":"C","text":"Prezența unei discontinuități marginale la interfața preparație/restaurare, evidențiată la palpare cu sonda."},{"id":"D","text":"Modificarea de culoare a marginilor de smalț în brun maroniu."},{"id":"E","text":"Prezența dentinei alterate la palparea în profunzime cu sonda."}],"correct":["C"],"pages":[43],"source":"set-2"},{"id":"set2-uA1cMU7n","fingerprint":"fea3790325980248","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"În situația unui pacient care acuză sensibilitate dureroasă fără a putea preciza dintele cauzal, ce metodă se utilizează pentru localizarea acestuia?","options":[{"id":"A","text":"Se recomandă efectuarea unei radiografii panoramice."},{"id":"B","text":"Se aplică un stimul rece pe fiecare dinte până la apariția durerii."},{"id":"C","text":"Se utilizează palparea cu sonda în profunzimea tuturor restaurărilor din zona respectivă."},{"id":"D","text":"Se realizează o inspecție vizuală amănunțită a suprafețelor dentare pentru modificări de culoare."},{"id":"E","text":"Se solicită pacientului să strângă dinții pe un rulou de vată foarte strâns sau pe un bețișor de lemn."}],"correct":["E"],"pages":[43],"source":"set-2"},{"id":"set2-2Gjog4Nk","fingerprint":"3764fc11e56594b1","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele semne clinice sunt utilizate pentru stabilirea diagnosticului pozitiv de carie secundară marginală?","options":[{"id":"A","text":"Colorație brun-cafenie a smalțului marginal restaurării."},{"id":"B","text":"Prezența la palpare cu sonda în profunzime a dentinei necrotice."},{"id":"C","text":"Absența oricărei modificări de culoare a obturației."},{"id":"D","text":"Probe de sensibilitate pulpară negative, indicând necroza pulpară."},{"id":"E","text":"Dinte cu obturație coronară care prezintă o soluție de continuitate între restaurare și țesutul dentar dur."}],"correct":["A","B","E"],"pages":[43],"source":"set-2"},{"id":"set2-Bg-l26SL","fingerprint":"2b86037f9b2dfe9e","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"În contextul diagnosticului diferențial pentru leziunile coronare, care sunt caracteristicile distinctive ale unei fracturi de origine traumatică?","options":[{"id":"A","text":"Apariția la scurt timp de la aplicarea unei restaurări, din cauza preparării incorecte a cavității."},{"id":"B","text":"Modificări de culoare ale smalțului și prezența unei soluții de continuitate la interfața dinte/restaurare."},{"id":"C","text":"Pierderi superficiale de material apărute la scurt timp de la realizarea restaurării."},{"id":"D","text":"Smalț de culoare normală, absența dentinei necrotice și un istoric anamnezic de traumatism."},{"id":"E","text":"Prezența dentinei necrotice sub o restaurare coronară bine adaptată marginal."}],"correct":["D"],"pages":[44],"source":"set-2"},{"id":"set2-yVmuB-9k","fingerprint":"4b2866cd798961c2","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt posibilele evoluții ale unei carii secundare marginale lăsate netratate?","options":[{"id":"A","text":"Evoluția spre profunzime, care poate determina gangrenă pulpară."},{"id":"B","text":"Vindecarea spontană prin mecanisme de remineralizare a smalțului."},{"id":"C","text":"Fracturarea marginilor preparației ca urmare a evoluției spre suprafață."},{"id":"D","text":"Fracturarea dintelui prin subminarea smalțului de către procesul carios."},{"id":"E","text":"Apariția durerii exclusiv spontane, neprovocate de excitanți."}],"correct":["A","C","D"],"pages":[44],"source":"set-2"},{"id":"set2-VlTa4vVK","fingerprint":"f01b9dbcbcc2b84b","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Cum se manifestă clinic recidiva de carie în stadiile sale precoce?","options":[{"id":"A","text":"Prin modificarea evidentă a culorii restaurării coronare."},{"id":"B","text":"Prin prezența unei soluții de continuitate vizibile la interfața dinte/restaurare."},{"id":"C","text":"Printr-o fractură a unui perete dentar, ca prim semn clinic."},{"id":"D","text":"Este o afecțiune inițial asimptomatică sau oligosimptomatică."},{"id":"E","text":"Prin durere intensă și spontană, similară unei pulpite acute ireversibile."}],"correct":["D"],"pages":[44],"source":"set-2"},{"id":"set2-dGMuX8PL","fingerprint":"e61b3a40f82289b8","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Ce elemente clinice pot fi identificate după îndepărtarea unei restaurări în cazul unui diagnostic de recidivă de carie?","options":[{"id":"A","text":"Deschiderea accidentală a camerei pulpare în cavitățile profunde."},{"id":"B","text":"O adaptare marginală incorectă a restaurării, cu spațiu de retenție."},{"id":"C","text":"Prezența dentinei necrotice pe peretele pulpar sau axial al cavității."},{"id":"D","text":"Absența durerii la îndepărtarea dentinei necrotice, indiferent de profunzimea leziunii."},{"id":"E","text":"Apariția sensibilității dureroase în timpul manevrelor de îndepărtare a dentinei necrotice."}],"correct":["A","C","E"],"pages":[44],"source":"set-2"},{"id":"set2-vdr5yc_7","fingerprint":"c64434fbc2f3ae4b","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele semne clinice sunt esențiale pentru stabilirea diagnosticului pozitiv de recidivă de carie?","options":[{"id":"A","text":"Absența sensibilității la testele de vitalitate pulpară."},{"id":"B","text":"Apariția semnelor clinice de carie simplă sau de complicație pulpară acută."},{"id":"C","text":"Evidențierea dentinei necrotice sub restaurare, după îndepărtarea acesteia."},{"id":"D","text":"Prezența unui dinte cu restaurare coronară bine adaptată marginal."},{"id":"E","text":"Prezența unei restaurări coronare cu adaptare marginală deficitară."}],"correct":["B","C","D"],"pages":[44],"source":"set-2"},{"id":"set2-4-ru8v3P","fingerprint":"9246415ae2183ecb","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este elementul cheie pentru diagnosticul diferențial între recidiva de carie și necroza pulpară pe un dinte cu o restaurare corectă?","options":[{"id":"A","text":"Simptomatologia dureroasă la excitanți chimici."},{"id":"B","text":"Modificarea de culoare a țesuturilor dure dentare."},{"id":"C","text":"Prezența sau absența dentinei necrotice sub restaurare."},{"id":"D","text":"Adaptarea marginală a restaurării coronare."},{"id":"E","text":"Starea camerei pulpare (deschisă sau închisă)."}],"correct":["C"],"pages":[44],"source":"set-2"},{"id":"set2-HkHs9QHb","fingerprint":"9dfb4bb7fb8855d7","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este principalul criteriu clinic care diferențiază caria secundară marginală de recidiva de carie?","options":[{"id":"A","text":"Localizarea dentinei necrotice exclusiv pe peretele pulpar."},{"id":"B","text":"Prezența durerii provocate de excitanți fizici/chimici."},{"id":"C","text":"Evoluția spre complicații pulpare, precum gangrena."},{"id":"D","text":"Existența unei soluții de discontinuitate la interfața dinte/restaurare."},{"id":"E","text":"Modificarea de culoare a smalțului adiacent restaurării."}],"correct":["D"],"pages":[44],"source":"set-2"},{"id":"set2-MQ6rEqfU","fingerprint":"be94d34676459a75","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt complicațiile posibile ale unei recidive de carie care evoluează fără tratament?","options":[{"id":"A","text":"Expulzarea spontană a materialului de restaurare."},{"id":"B","text":"Progresia spre gangrenă pulpară."},{"id":"C","text":"Ameliorarea simptomelor prin sclerozarea dentinei."},{"id":"D","text":"Apariția unei inflamații pulpare acute."},{"id":"E","text":"Fracturarea pereților dentari din cauza subminării țesuturilor dure."}],"correct":["B","D","E"],"pages":[44],"source":"set-2"},{"id":"set2-VI-TMfLF","fingerprint":"4fc0cdc367604972","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Conform sistemului ICDAS, care dintre următoarele criterii sunt utilizate pentru depistarea leziunilor carioase?","options":[{"id":"A","text":"Evaluarea prezenței și gradului de afectare a unei suprafețe adiacente unei sigilări sau restaurări."},{"id":"B","text":"Partea anatomică evaluată, fie coroană, fie rădăcină."},{"id":"C","text":"Prezența bolilor sistemice asociate."},{"id":"D","text":"Vârsta pacientului și obiceiurile alimentare."},{"id":"E","text":"Topografia suprafețelor dentare, precum șanțuri, fosete sau suprafețe netede."}],"correct":["A","B","E"],"pages":[45],"source":"set-2"},{"id":"set2-IBRIqSU3","fingerprint":"550aff987a5dd6e9","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele condiții ale unei suprafețe dentare ar fi clasificate cu Cod 0 în sistemul ICDAS?","options":[{"id":"A","text":"O opacitate carioasă vizibilă doar după uscarea suprafeței timp de 5 secunde."},{"id":"B","text":"O suprafață cu hipoplazie de smalț."},{"id":"C","text":"Uzura dentară prin atriție sau abraziune."},{"id":"D","text":"Prezența fluorozei dentare."},{"id":"E","text":"O colorație maronie mai extinsă decât șanțurile, vizibilă pe dintele umed."}],"correct":["B","C","D"],"pages":[45],"source":"set-2"},{"id":"set2-f1o0MCix","fingerprint":"378f6a828f6832cb","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este diferența principală între o leziune carioasă Cod 1 și una Cod 2 în sistemul ICDAS, pe suprafețe cu șanțuri și fosete?","options":[{"id":"A","text":"Leziunea Cod 2 implică expunerea vizibilă a dentinei, în timp ce leziunea Cod 1 este limitată la smalț."},{"id":"B","text":"Leziunea Cod 1 prezintă un halou întunecat de la nivel dentinar, spre deosebire de Codul 2."},{"id":"C","text":"Leziunea Cod 1 implică o distrucție localizată în smalț, în timp ce leziunea Cod 2 nu."},{"id":"D","text":"Leziunea Cod 1 este întotdeauna de tip 'white-spot', iar Codul 2 este de tip 'brown-spot'."},{"id":"E","text":"Leziunea Cod 2 este vizibilă pe suprafața umedă, în timp ce leziunea Cod 1 devine vizibilă doar după uscare."}],"correct":["E"],"pages":[45],"source":"set-2"},{"id":"set2-XBaZBgU5","fingerprint":"b7f9c91328b06b14","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce caracteristică definește o leziune carioasă clasificată drept Cod 3 conform sistemului ICDAS?","options":[{"id":"A","text":"O cavitate distinctă în smalț cu expunerea evidentă a dentinei subiacente."},{"id":"B","text":"O opacitate de tip 'white-spot' vizibilă pe suprafața umedă, dar fără pierderea continuității suprafeței."},{"id":"C","text":"O modificare de culoare vizibilă doar după uscare prelungită, fără pierdere de substanță."},{"id":"D","text":"O umbră întunecată provenită de la dentină, vizibilă prin transparența smalțului."},{"id":"E","text":"O distrucție localizată a smalțului, observabilă după uscare, fără semne vizibile de afectare dentinară."}],"correct":["E"],"pages":[45],"source":"set-2"},{"id":"set2--muCRGn6","fingerprint":"c44f54c2b855543f","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Un pacient prezintă un dinte cu o umbră de dentină colorată, vizibilă prin transparența smalțului aparent intact. Nu există o cavitate evidentă. Cum se clasifică această leziune conform ICDAS?","options":[{"id":"A","text":"Cod 4"},{"id":"B","text":"Cod 2"},{"id":"C","text":"Cod 5"},{"id":"D","text":"Cod 1"},{"id":"E","text":"Cod 3"}],"correct":["A"],"pages":[45],"source":"set-2"},{"id":"set2-AqxjOX9g","fingerprint":"f235c972db3ce58f","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce descrie cel mai bine o leziune carioasă ICDAS Cod 6?","options":[{"id":"A","text":"O leziune cavitară distinctă cu expunerea dentinei subiacente, fără a se specifica extinderea."},{"id":"B","text":"O modificare de culoare sub formă de halou întunecat, fără expunerea dentinei."},{"id":"C","text":"O distrucție localizată la nivelul smalțului, vizibilă doar după uscare."},{"id":"D","text":"O cavitate profundă și extinsă, cu dentină vizibilă atât pe podea, cât și pe pereții laterali."},{"id":"E","text":"O modificare distinctă de culoare la nivelul smalțului, vizibilă pe dintele umed."}],"correct":["D"],"pages":[45],"source":"set-2"},{"id":"set2-2tbDQIh7","fingerprint":"14b369f4a93d09b5","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este diferența principală dintre o leziune carioasă proximală cod 1 și una cod 2?","options":[{"id":"A","text":"Utilizarea sondei este necesară pentru confirmarea codului 1, dar nu și pentru codul 2."},{"id":"B","text":"Leziunea cod 2 este întotdeauna de culoare brună, în timp ce leziunea cod 1 este întotdeauna albă."},{"id":"C","text":"Leziunea cod 1 este vizibilă doar după uscare intensă, în timp ce leziunea cod 2 este vizibilă pe dintele umed."},{"id":"D","text":"Cod 1 descrie o cavitate evidentă, în timp ce cod 2 descrie doar o modificare de culoare."},{"id":"E","text":"Cod 2 implică o umbră a dentinei subiacente, pe când cod 1 afectează doar smalțul superficial."}],"correct":["C"],"pages":[46],"source":"set-2"},{"id":"set2-QD8ia3Dz","fingerprint":"ba84aa5f3ec2ccf8","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Un pacient prezintă o zonă de culoare gri-albăstruie vizibilă prin creasta marginală intactă a unui premolar. Suprafața smalțului pare integră la inspecția vizuală. Ce cod descrie cel mai bine această leziune pe o suprafață proximală?","options":[{"id":"A","text":"Cod 5"},{"id":"B","text":"Cod 2"},{"id":"C","text":"Cod 1"},{"id":"D","text":"Cod 4"},{"id":"E","text":"Cod 3"}],"correct":["D"],"pages":[46],"source":"set-2"},{"id":"set2-6sdP70N5","fingerprint":"b4e0c33eee6a753e","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele afirmații descriu o leziune carioasă proximală cod 6?","options":[{"id":"A","text":"Implică o extindere de cel puțin jumătate din suprafața dentară."},{"id":"B","text":"Este posibilă o afectare a pulpei coronare."},{"id":"C","text":"Creasta marginală este întotdeauna intactă."},{"id":"D","text":"Reprezintă o cavitate profundă cu dentină vizibilă atât pe pereți, cât și la nivelul bazei."},{"id":"E","text":"Se caracterizează printr-o umbră a dentinei, fără pierderea integrității smalțului."}],"correct":["A","B","D"],"pages":[46],"source":"set-2"},{"id":"set2-socXQDnI","fingerprint":"21a693618321358e","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"La examinarea unui dinte pe suprafața vestibulară se observă o opacitate în apropierea marginii gingivale, care nu se înscrie în aspectul normal al smalțului și este vizibilă pe dintele umed. Ce cod i se atribuie acestei leziuni pe o suprafață netedă?","options":[{"id":"A","text":"Cod 3"},{"id":"B","text":"Cod 4"},{"id":"C","text":"Cod 0"},{"id":"D","text":"Cod 2"},{"id":"E","text":"Cod 1"}],"correct":["D"],"pages":[46],"source":"set-2"},{"id":"set2-eaRJdixI","fingerprint":"67cbcd20aeaa773a","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este primul semn vizual de carie care poate fi detectat adiacent unei restaurări sau sigilări?","options":[{"id":"A","text":"O cavitate evidentă cu dentină vizibilă la marginea restaurării."},{"id":"B","text":"O opacitate sau colorație vizibilă doar după uscarea prelungită cu aer."},{"id":"C","text":"O pierdere distinctă a integrității smalțului marginal."},{"id":"D","text":"O zonă opacă sau colorată, vizibilă pe dintele umed, la joncțiunea cu sigilarea."},{"id":"E","text":"O umbră întunecată a dentinei sub smalțul adiacent restaurării."}],"correct":["B"],"pages":[46],"source":"set-2"},{"id":"set2-M8BIs8P9","fingerprint":"dc9f2d88db7034dc","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Ce afecțiuni sau stări ale suprafeței dentare, în afara sănătății carioase, sunt înregistrate cu codul 0?","options":[{"id":"A","text":"Hipoplazia de smalț"},{"id":"B","text":"O opacitate albă vizibilă doar după uscare intensă"},{"id":"C","text":"Fluoroza"},{"id":"D","text":"Uzura dentară prin atriție, abraziune și eroziune"},{"id":"E","text":"Colorații extrinseci sau intrinseci"}],"correct":["A","C","D","E"],"pages":[46],"source":"set-2"},{"id":"set2-ouMjH-XU","fingerprint":"64ee5f9952271a38","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"În cazul unei leziuni carioase proximale cod 3, care este caracteristica definitorie vizibilă după uscarea intensă a dintelui timp de 5 secunde?","options":[{"id":"A","text":"O umbră a dentinei pigmentate vizibilă prin creasta marginală."},{"id":"B","text":"O pierdere a integrității suprafeței smalțului."},{"id":"C","text":"O modificare de culoare vizibilă și pe dintele umed."},{"id":"D","text":"O cavitate evidentă cu expunerea dentinei."},{"id":"E","text":"O opacitate carioasă albă sau brună fără pierderea integrității smalțului."}],"correct":["B"],"pages":[46],"source":"set-2"},{"id":"set2-LLtgx1PZ","fingerprint":"adec34768707a675","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce cod este atribuit unei leziuni carioase adiacente unei restaurări, caracterizată printr-o modificare vizuală distinctă, opacă sau colorată (albă/brună), vizibilă pe smalțul umed?","options":[{"id":"A","text":"Cod 1"},{"id":"B","text":"Cod 4"},{"id":"C","text":"Cod 3"},{"id":"D","text":"Cod 2"},{"id":"E","text":"Cod 0"}],"correct":["D"],"pages":[47],"source":"set-2"},{"id":"set2-WsDI65IA","fingerprint":"b6b498bccc5bb4ed","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele descrieri corespund leziunilor carioase asociate cu restaurări ce implică dentină vizibilă sau expusă?","options":[{"id":"A","text":"O modificare vizuală a smalțului, vizibilă doar după uscare prelungită cu aer."},{"id":"B","text":"O leziune carioasă mai mică de 0,5 mm, cu o umbră determinată de culoarea dentinei, dar fără expunere directă."},{"id":"C","text":"O cavitate adiacentă unei restaurări cu o lipsă de substanță dură dentară mai mare de 0,5 mm și dentină expusă."},{"id":"D","text":"Carii marginale care prezintă dentină necrotică subiacentă, dar fără dentină vizibilă direct."},{"id":"E","text":"O cavitate extinsă în profunzime sau suprafață, unde dentina este vizibilă atât pe pereții cavității, cât și la nivelul peretelui pulpar/parapulpar."}],"correct":["C","E"],"pages":[47],"source":"set-2"},{"id":"set2-SSAZxFoB","fingerprint":"06ea663304814c63","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt proprietățile fundamentale ale radiațiilor Rontgen care permit obținerea imaginilor radiologice dentare?","options":[{"id":"A","text":"Ionizarea variabilă a suprafeței senzorului, corespunzător țesuturilor traversate."},{"id":"B","text":"Capacitatea de a induce fluorescență în smalțul dentar."},{"id":"C","text":"Absorbția variabilă a acestora de către țesuturi cu densități anatomice diferite."},{"id":"D","text":"Reflexia selectivă a radiațiilor de către camera pulpară."},{"id":"E","text":"Penetrabilitatea acestora prin țesuturi."}],"correct":["A","C","E"],"pages":[47],"source":"set-2"},{"id":"set2-NgmcUIk0","fingerprint":"df76da884e6f6e61","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Cum apare pe o imagine radiologică o structură anatomică densă, precum smalțul coronar?","options":[{"id":"A","text":"Ca o zonă invizibilă, deoarece absoarbe complet radiațiile."},{"id":"B","text":"Ca o zonă de radiotransparență, cu nuanțe de gri închis spre negru."},{"id":"C","text":"Ca o imagine cu contururi șterse și omogenitate neuniformă."},{"id":"D","text":"Ca o zonă de radioopacitate, cu nuanțe de gri deschis spre alb."},{"id":"E","text":"Ca o imagine cu intensitate radiologică redusă."}],"correct":["D"],"pages":[47],"source":"set-2"},{"id":"set2-QLSW76KX","fingerprint":"d311a33df44b79aa","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt afirmațiile corecte referitoare la aspectul radiologic al structurilor dentare coronare în condiții normale?","options":[{"id":"A","text":"Camera pulpară este o porțiune de radiotransparență cu o tentă cenușiu închisă."},{"id":"B","text":"Dentina coronară are o radioopacitate mai mare decât smalțul."},{"id":"C","text":"Grosimea smalțului este uniformă de la suprafața ocluzală până la joncțiunea cu cementul."},{"id":"D","text":"Smalțul coronar se prezintă ca zona cu cea mai mare radioopacitate."},{"id":"E","text":"Contururile periferice ale coroanei și camerei pulpare sunt, în mod normal, șterse și difuze."}],"correct":["A","D"],"pages":[47],"source":"set-2"},{"id":"set2-jjlFbCJ0","fingerprint":"13611b2868bf1e4b","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este elementul distinctiv principal între o leziune carioasă adiacentă unei restaurări codificată cu Cod 1 și una codificată cu Cod 2?","options":[{"id":"A","text":"Prezența dentinei necrotice subiacente vizibilă prin smalț."},{"id":"B","text":"Prezența unei cavități mai mari de 0,5 mm."},{"id":"C","text":"Existența unei umbre determinate de culoarea dentinei."},{"id":"D","text":"Vizibilitatea modificării de culoare pe suprafața umedă a dintelui."},{"id":"E","text":"Localizarea leziunii exclusiv în cementul radicular."}],"correct":["D"],"pages":[47],"source":"set-2"},{"id":"set2-HX_XWQLm","fingerprint":"762e5b6a29e96bd6","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Ce elemente definesc o leziune carioasă de Cod 5 adiacentă unei restaurări sau sigilări?","options":[{"id":"A","text":"O modificare vizuală a smalțului, fără pierdere de substanță detectabilă clinic."},{"id":"B","text":"O umbră determinată de culoarea dentinei, sub un smalț aparent integru."},{"id":"C","text":"O cavitate extinsă, în care dentina este vizibilă atât pe pereți, cât și la nivelul peretelui pulpar."},{"id":"D","text":"O cavitate cu lipsă de substanță dură dentară mai mare de 0,5 mm și dentină expusă."},{"id":"E","text":"O discontinuitate la nivelul marginilor restaurării detectabilă prin introducerea vârfului unei sonde de 0,5 mm."}],"correct":["D","E"],"pages":[47],"source":"set-2"},{"id":"set2-uqIbCOmF","fingerprint":"65377a31e24d04b8","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este procentul minim de demineralizare necesar pentru ca o leziune carioasă să fie vizibilă radiologic la utilizarea senzorilor digitali, comparativ cu senzorii clasici?","options":[{"id":"A","text":"Minim 30% pentru ambele tipuri de senzori."},{"id":"B","text":"Minim 5-10% pentru ambele tipuri de senzori."},{"id":"C","text":"Minim 30% pentru senzorii digitali și minim 5-10% pentru senzorii clasici."},{"id":"D","text":"Minim 5-10% pentru senzorii digitali și minim 30% pentru senzorii clasici."},{"id":"E","text":"Nu există un prag minim de demineralizare pentru senzorii digitali."}],"correct":["D"],"pages":[48],"source":"set-2"},{"id":"set2-oHHNLi3D","fingerprint":"4e21df82c57b90a4","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următorii factori influențează capacitatea de detecție radiologică a cariilor dentare?","options":[{"id":"A","text":"Condițiile de examinare."},{"id":"B","text":"Tipul de film radiologic utilizat (intraoral sau extraoral)."},{"id":"C","text":"Subiectivismul și gradul de pregătire al examinatorului."},{"id":"D","text":"Calitatea imaginii radiologice."},{"id":"E","text":"Vârsta pacientului și densitatea osoasă alveolară."}],"correct":["A","C","D"],"pages":[48],"source":"set-2"},{"id":"set2-rNLecqTK","fingerprint":"d666c94b3c861c81","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce aspect radiologic este caracteristic pentru o carie proximală în stadiul I (incipient), limitată la smalț?","options":[{"id":"A","text":"Două triunghiuri radiotransparente, unul în smalț și celălalt extins în dentină."},{"id":"B","text":"O imagine de farfurie, extinsă în suprafață și cu profunzime redusă."},{"id":"C","text":"O radiotransparență cenușie, semilunară, cu contururi șterse, în jumătatea externă a smalțului."},{"id":"D","text":"O radiotransparență triunghiulară cu baza largă spre suprafața dintelui, în jumătatea internă a smalțului."},{"id":"E","text":"O radiotransparență rotundă, bine delimitată, sub joncțiunea smalț-dentină."}],"correct":["C"],"pages":[48],"source":"set-2"},{"id":"set2-Glf55NH5","fingerprint":"b8f177d5883a9716","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Conform indexului radiologic pentru carii proximale, ce stadiu este descris de o radiotransparență triunghiulară cu unghiuri rotunjite, cu baza spre suprafața dintelui și vârful spre joncțiunea smalț-dentină, extinsă în jumătatea internă a smalțului?","options":[{"id":"A","text":"Stadiul III sau avansat."},{"id":"B","text":"Niciun stadiu, deoarece cariile în smalț nu sunt clasificabile radiologic."},{"id":"C","text":"Stadiul II sau moderat."},{"id":"D","text":"Stadiul I sau incipient."},{"id":"E","text":"Stadiul IV sau sever."}],"correct":["C"],"pages":[48],"source":"set-2"},{"id":"set2-9RIFWesJ","fingerprint":"f77027a075d757e7","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile radiologice ale cariei proximale în stadiul III (avansat), care afectează atât smalțul, cât și dentina?","options":[{"id":"A","text":"Se observă două triunghiuri radiotransparente, unul mai redus localizat în dentină, celălalt mai extins localizat în smalț."},{"id":"B","text":"Radiotransparența din dentină se întinde în jumătatea externă a grosimii acesteia."},{"id":"C","text":"Triunghiul din dentină are baza spre joncțiunea smalț-dentină și vârful spre camera pulpară."},{"id":"D","text":"Imaginea bipolară își pierde individualitatea, făcând loc unei radiotransparențe mari, atipice."},{"id":"E","text":"Triunghiul din smalț are baza la joncțiunea smalț-dentină."}],"correct":["B","C"],"pages":[48],"source":"set-2"},{"id":"set2-GdyXHMaT","fingerprint":"b70fa68997de71d8","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce caracterizează din punct de vedere radiologic stadiul IV (sever) al cariei proximale?","options":[{"id":"A","text":"O imagine bipolară clară, cu un triunghi în smalț și un triunghi în jumătatea externă a dentinei."},{"id":"B","text":"O radiotransparență triunghiulară extinsă până la joncțiunea smalț-dentină, fără a o depăși."},{"id":"C","text":"O radiotransparență semilunară limitată la smalțul extern."},{"id":"D","text":"O radiotransparență mare, cu forme atipice, localizată în jumătatea internă a dentinei."},{"id":"E","text":"O radiotransparență rotundă, similară celei de pe fețele vestibulare."}],"correct":["D"],"pages":[48],"source":"set-2"},{"id":"set2-W3u4ChBY","fingerprint":"2c570fe089693126","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"De ce este dificil de realizat radiodiagnosticul precoce al cariei ocluzale în smalț?","options":[{"id":"A","text":"Deoarece leziunile incipiente au o formă de farfurie care se confundă cu anatomia normală."},{"id":"B","text":"Deoarece fenomenul de burn-out este foarte pronunțat în zona ocluzală."},{"id":"C","text":"Deoarece cariile ocluzale nu devin radiotransparente decât după ce ajung la camera pulpară."},{"id":"D","text":"Deoarece smalțul ocluzal este prea subțire pentru a permite vizualizarea leziunii."},{"id":"E","text":"Deoarece leziunea este mascată radiografic de grosimea smalțului cuspizilor."}],"correct":["E"],"pages":[48],"source":"set-2"},{"id":"set2-8jmj-TOt","fingerprint":"7968574a5faca951","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este aspectul radiologic general al unei carii simple la nivelul fețelor vestibulare sau orale?","options":[{"id":"A","text":"O radiotransparență rotundă pentru leziunile mici și ovalară sau semilunară pentru cele mai mari."},{"id":"B","text":"O imagine bipolară cu două radiotransparențe distincte."},{"id":"C","text":"O imagine de farfurie, extinsă în suprafață."},{"id":"D","text":"Sunt vizibile doar ca o ancoșă discretă la nivelul smalțului."},{"id":"E","text":"O radiotransparență triunghiulară cu baza spre joncțiunea smalț-dentină."}],"correct":["A"],"pages":[48],"source":"set-2"},{"id":"set2-zU0FF5I6","fingerprint":"1c9eea817eee7b0a","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Referitor la aspectele radiologice ale cariei de colet, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Sunt greu de observat radiologic, fiind mascate de grosimea smalțului cervical."},{"id":"B","text":"Prezintă întotdeauna o formă triunghiulară, similară cariilor proximale."},{"id":"C","text":"Diagnosticul în această zonă poate fi îngreunat de fenomenul de burn-out."},{"id":"D","text":"Inițial, prezintă frecvent imagini \"de farfurie\" datorită extinderii în suprafață."},{"id":"E","text":"În stadii avansate, radiotransparența se situează imediat sub limita apicală a smalțului."}],"correct":["C","D","E"],"pages":[48],"source":"set-2"},{"id":"set2-AP2zpGOV","fingerprint":"d838cd69c0840488","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile radiologice ale recidivei de carie?","options":[{"id":"A","text":"Limita de trecere spre dentină este netă și bine conturată."},{"id":"B","text":"Sunt reprezentate de zone radiotransparente, semilunare sau curbiliniare, de dimensiuni mici."},{"id":"C","text":"Evoluează întotdeauna spre camera pulpară, având contururi complet șterse."},{"id":"D","text":"Se localizează între obturație și dentina subiacentă."},{"id":"E","text":"Limita de trecere spre materialul de obturație este ștearsă și difuză."}],"correct":["B","D"],"pages":[49],"source":"set-2"},{"id":"set2-he9188U4","fingerprint":"038fc1fa5a09673e","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Ce aspect radiologic la nivelul coletului dentar poate conduce la un diagnostic fals de carie simplă?","options":[{"id":"A","text":"O radiotransparență cu contururi nete la marginea unei obturații."},{"id":"B","text":"O radioopacitate moderată cu contururi specifice cavităților neretentive."},{"id":"C","text":"O înnegrire sau o voalare cenușiu-închisă a zonei."},{"id":"D","text":"O radioopacitate intensă cu contururi nete caracteristice unei cavități."},{"id":"E","text":"O zonă radiotransparentă semilunară între o obturație și dentină."}],"correct":["C"],"pages":[49],"source":"set-2"},{"id":"set2-7s_wgv0g","fingerprint":"1d08a4a3e56fce6a","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care dintre următoarele descrie corect aspectul radiologic al cariei secundare marginale?","options":[{"id":"A","text":"O imagine exclusiv clinică, de tipul unei voalări cenușii, fără corespondent radiologic."},{"id":"B","text":"O radiotransparență situată la marginea obturației, cu evoluție spre camera pulpară și contururi nete la limita cu materialul de obturație."},{"id":"C","text":"O radioopacitate intensă care urmărește conturul unei cavități neretentive."},{"id":"D","text":"O zonă radiotransparentă de mici dimensiuni, curbiliniară, localizată între obturație și dentina subiacentă."},{"id":"E","text":"O imagine cu contururi șterse atât spre materialul de obturație, cât și spre dentină."}],"correct":["B"],"pages":[49],"source":"set-2"},{"id":"set2-z4Oj3DmC","fingerprint":"4176aa3ad1a3deb1","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Selectați afirmațiile corecte privind aspectele radiologice ale diferitelor materiale de restaurare coronară.","options":[{"id":"A","text":"Materialele compozite radiotransparente se vizualizează ca o radioopacitate moderată, în cavități cu geometrie neretentivă."},{"id":"B","text":"Toate materialele de restaurare coronară se asociază cu cavități neretentive."},{"id":"C","text":"Obturațiile de bază din materiale radioopace se caracterizează printr-o radioopacitate intensă în cavități cu geometrie retentivă."},{"id":"D","text":"Materialele aderente radioopace au o radioopacitate mai intensă comparativ cu amalgamul dentar."},{"id":"E","text":"Obturațiile de durată din amalgam prezintă radioopacitate intensă și contururi nete, specifice cavităților retentive."}],"correct":["A","E"],"pages":[49],"source":"set-2"},{"id":"set2-YFx3hIPC","fingerprint":"da70acc60bb3ce23","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Cum se diferențiază radiologic o obturație din amalgam de una din materiale aderente radioopace?","options":[{"id":"A","text":"Amalgamul prezintă o radioopacitate mai puțin intensă."},{"id":"B","text":"Ambele materiale prezintă aceeași intensitate a radioopacității, dar contururi diferite."},{"id":"C","text":"Amalgamul are o radioopacitate mai intensă decât materialele aderente radioopace."},{"id":"D","text":"Amalgamul se asociază cu cavități neretentive, iar materialele aderente cu cavități retentive."},{"id":"E","text":"Materialele aderente sunt asociate cu cavități de geometrie retentivă."}],"correct":["C"],"pages":[49],"source":"set-2"},{"id":"set2-_FXaJoX1","fingerprint":"ea8772b55b5c905c","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile leziunilor carioase cu evoluție rapidă?","options":[{"id":"A","text":"Sunt caracteristice vârstelor tinere."},{"id":"B","text":"Sunt cunoscute și sub denumirea de carii umede."},{"id":"C","text":"Dentina alterată prezintă o culoare brună-cafenie."},{"id":"D","text":"Se localizează pe suprafețele libere ale dinților expuse autocurățirii."},{"id":"E","text":"Prezintă depozite bogate de dentină alterată de consistență moale."}],"correct":["A","B","E"],"pages":[38],"source":"set-2"},{"id":"set2-Lb4OXTGg","fingerprint":"fbf12cbd96a2839c","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"În cazul leziunilor carioase de adâncime medie, care este grosimea stratului de dentină dură sănătoasă interpus între procesul carios și camera pulpară?","options":[{"id":"A","text":"2-3 mm"},{"id":"B","text":"0,5-1 mm"},{"id":"C","text":"1-2 mm"},{"id":"D","text":"Peste 4 mm"},{"id":"E","text":"3-4 mm"}],"correct":["A"],"pages":[38],"source":"set-2"},{"id":"set2-czqwJaoP","fingerprint":"fd3bf95cdbf01105","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele afirmații descriu leziunile carioase clasificate în funcție de momentul apariției și legătura cu o restaurare existentă?","options":[{"id":"A","text":"Caria secundară marginală se dezvoltă sub materialul restaurator."},{"id":"B","text":"Cariile primare apar în urma unui atac carios primar, pe un dinte clinic sănătos, indemn de carie."},{"id":"C","text":"Recidiva de carie este o leziune situată sub materialul restaurator."},{"id":"D","text":"Cariile secundare apar pe un dinte pe care există deja o restaurare directă sau indirectă."},{"id":"E","text":"Recidiva de carie reprezintă o leziune localizată la interfața dintre preparație și restaurare."}],"correct":["B","C","D"],"pages":[38],"source":"set-2"},{"id":"set2-LJMe5G1i","fingerprint":"7454139db4de0a41","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Referitor la procesul de diagnostic al leziunilor carioase, care dintre următoarele afirmații sunt exacte?","options":[{"id":"A","text":"Examenul clinic se realizează după igienizarea profesională a arcadelor dentare și a țesuturilor parodontale învecinate."},{"id":"B","text":"Identificarea pierderilor minime de țesut dentar este îngreunată de lipsa de vizibilitate în zonele suprafețelor de contact interdentar, fisurilor și șanțurilor."},{"id":"C","text":"Precizarea momentului de tranziție a unei leziuni de la faza de demineralizare la faza de leziune cavitară se realizează fără dificultăți."},{"id":"D","text":"În foaia de observație, resturile radiculare sunt menționate prin abrevierea CS."},{"id":"E","text":"Diagnosticul reprezintă o metodă obiectivă de determinare a prezenței semnelor și simptomelor unei boli."}],"correct":["A","B"],"pages":[38],"source":"set-2"},{"id":"set2-7s5CPKbP","fingerprint":"200f8561c81ebe0e","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Ce caracteristici descriu leziunile carioase staționare?","options":[{"id":"A","text":"Prezintă o cantitate mare de dentină alterată de culoare gălbuie."},{"id":"B","text":"Suprafața smalțului afectat este perfect netedă."},{"id":"C","text":"Apar pe suprafețele libere ale dinților expuse autocurățirii și curățirii artificiale."},{"id":"D","text":"Sunt oprite din evoluție."},{"id":"E","text":"Se prezintă clinic sub forma unor pete brune-maronii ale smalțului."}],"correct":["C","D","E"],"pages":[38],"source":"set-2"},{"id":"set2-jtEgU374","fingerprint":"11e7ac4d006d2148","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile unui test ideal de detecție a leziunilor dentare?","options":[{"id":"A","text":"Non-invazivitatea și rapiditatea în aplicare."},{"id":"B","text":"Caracterul subiectiv, permițând clinicianului o adaptare individuală a rezultatelor."},{"id":"C","text":"Specificitatea și senzitivitatea metodei."},{"id":"D","text":"Capacitatea de a furniza date simple, certe și corelabile cu evoluția biologică a structurii investigate."},{"id":"E","text":"Necesitatea unei dotări tehnice complexe și deosebite."}],"correct":["A","C","D"],"pages":[39],"source":"set-2"},{"id":"set2-9EJWXZry","fingerprint":"e8b3c6f32fb482d5","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele tehnici reprezintă metode clinice directe de detecție a leziunilor dentare?","options":[{"id":"A","text":"Metoda vizual-tactilă."},{"id":"B","text":"Diafanoscopia FOTI și DIFOTI."},{"id":"C","text":"Starea gingiei."},{"id":"D","text":"Markerii coloranți."},{"id":"E","text":"Semnul firului de mătase."}],"correct":["A","C","E"],"pages":[39],"source":"set-2"},{"id":"set2-7l1Oc7cw","fingerprint":"5c9b304c182b327f","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele investigații sunt considerate metode clinice indirecte (alternative) de detecție a leziunilor carioase?","options":[{"id":"A","text":"Metoda vizuală cu separare temporară a dinților."},{"id":"B","text":"Tehnicile ultrasonice."},{"id":"C","text":"Fisurotomia."},{"id":"D","text":"Spectroscopia laser."},{"id":"E","text":"Fluorescența QLF."}],"correct":["B","D","E"],"pages":[39],"source":"set-2"},{"id":"set2-_l1JtPPd","fingerprint":"959d38ad871a9719","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care dintre următoarele proceduri reprezintă o metodă exploratorie utilizată pentru a facilita îndepărtarea depozitelor și confirmarea diagnosticului prezumptiv al leziunilor dentare?","options":[{"id":"A","text":"Aer abraziunea."},{"id":"B","text":"Radiografia asistată de computer."},{"id":"C","text":"Metodele electrice de detecție."},{"id":"D","text":"Markerii coloranți."},{"id":"E","text":"Examinarea cu ajutorul videoscopului."}],"correct":["A"],"pages":[39],"source":"set-2"},{"id":"set2-vn5pZ4QV","fingerprint":"36e8a6669fbda1c6","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele reprezintă localizări tipice ale leziunilor carioase situate în șanțuri și fosete?","options":[{"id":"A","text":"Fețele ocluzale ale molarilor și premolarilor."},{"id":"B","text":"Treimea de colet a fețelor vestibulare ale incisivilor."},{"id":"C","text":"Fosetele de pe fețele vestibulare și orale ale molarilor."},{"id":"D","text":"Fosetele de pe suprafețele palatinale ale incisivilor centrali și laterali superiori."},{"id":"E","text":"Fețele proximale ale premolarilor inferiori."}],"correct":["A","C","D"],"pages":[39],"source":"set-2"},{"id":"set2-wS6ruqj8","fingerprint":"3fe0519741c34ec5","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la caracteristicile clinice ale leziunilor necavitare și ale celor cu demineralizare avansată?","options":[{"id":"A","text":"Leziunile de demineralizare avansată cu evoluție lentă prezintă o colorație galben-brună și un caracter staționar."},{"id":"B","text":"Leziunile necavitare se caracterizează printr-o ușoară modificare de transluciditate și o suprafață dentară aparent sănătoasă."},{"id":"C","text":"Leziunile de demineralizare avansată cu evoluție rapidă capătă un aspect alb, dur și lucios."},{"id":"D","text":"Diagnosticul leziunilor necavitare se realizează facil prin utilizarea mijloacelor de detecție uzuale."},{"id":"E","text":"Sonda standard, ascuțită, este instrumentul indicat de primă intenție pentru explorarea zonelor demineralizate."}],"correct":["A","B","C"],"pages":[40],"source":"set-2"},{"id":"set2-dmq0OZlD","fingerprint":"dd74cde1a316030d","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele afirmații descriu corect morfologia și evoluția leziunilor carioase cavitare din șanțuri și fosete?","options":[{"id":"A","text":"Leziunea medie se dezvoltă profund în dentină și determină subminarea marcată a cuspizilor."},{"id":"B","text":"Leziunea superficială se prezintă ca o microcavitație, iar zona externă a dentinei poate prezenta o colorație cenușie."},{"id":"C","text":"Leziunea cu afectarea dentinei circumpulpare este însoțită de o iminență a deschiderii camerei pulpare și riscul complicațiilor aferente."},{"id":"D","text":"Leziunea profundă pătrunde în zona profundă a dentinei, înregistrând prezența dentinei necrotice și o subminare parțială a cuspizilor."},{"id":"E","text":"Leziunile cavitare cu evoluție rapidă în profunzime prezintă, de regulă, o deschidere extrem de largă la suprafața ocluzală."}],"correct":["B","C","D"],"pages":[40],"source":"set-2"},{"id":"set2-iqn3FnCr","fingerprint":"ed55ce0de34b685a","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este recomandarea specifică referitoare la explorarea instrumentală pentru detectarea cavitației la nivelul leziunilor din șanțuri și fosete?","options":[{"id":"A","text":"Explorarea ascuțită este indicată doar atunci când zona de smalț capătă o colorație brună-cafenie pe fondul unei evoluții rapide."},{"id":"B","text":"Se utilizează exclusiv sonda cu bilă, evitându-se tehnicile de palpare intempestivă."},{"id":"C","text":"Sonda cu bilă este rezervată în exclusivitate decelării absenței demineralizării smalțului din stadiul incipient."},{"id":"D","text":"Sonda standard ascuțită se folosește în mod optim pentru evaluarea subminării cuspizilor în stadiile medii."},{"id":"E","text":"Leziunile necavitare se evidențiază obligatoriu prin testarea durității la nivelul suprafeței cu ajutorul mijloacelor de detecție uzuale."}],"correct":["B"],"pages":[39],"source":"set-2"},{"id":"set2-iUN4TZ1P","fingerprint":"4f2cdabe6325d29b","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Prin ce semn clinic se evidențiază faza în care o leziune carioasă, localizată deasupra ariei de contact a molarilor sau premolarilor, subminează creasta marginală?","options":[{"id":"A","text":"Prin apariția petei albe cretoase la nivelul crestei marginale."},{"id":"B","text":"Prin prezența unei papile interdentare edemațiate, de culoare roșie-violacee."},{"id":"C","text":"Prin modificarea de culoare extinsă exclusiv spre unghiul incizal."},{"id":"D","text":"Prin pierderea de substanță dentară ce permite pătrunderea directă cu sonda în procesul carios."},{"id":"E","text":"Prin prezența unei zone de smalț lipsită de transparență la transiluminare pe mijlocul feței proximale."}],"correct":["A"],"pages":[40],"source":"set-2"},{"id":"set2-aZJPoqNN","fingerprint":"c91a8bad883882d9","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Ce metode sunt indicate pentru confirmarea diagnosticului în cazul cariilor incipiente situate la nivelul ariei de contact a molarilor care prezintă suprafețe strânse de contact proximale, când palparea este imposibilă?","options":[{"id":"A","text":"Separarea dinților exclusiv cu separatorul Ivory."},{"id":"B","text":"Separarea dentară lentă."},{"id":"C","text":"Palparea directă cu sonda dreaptă."},{"id":"D","text":"Examenul radiologic."},{"id":"E","text":"Transiluminarea zonei interesate."}],"correct":["B","D"],"pages":[40],"source":"set-2"},{"id":"set2-DU5AQbhm","fingerprint":"f462becd079c007b","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile leziunilor carioase situate sub aria de contact a molarilor și premolarilor?","options":[{"id":"A","text":"Produc în mod constant subminarea directă a crestei marginale, creând o pată albă cretoasă."},{"id":"B","text":"Interesează în timpul evoluției cementul radicular."},{"id":"C","text":"Sunt diagnosticate prin palparea cu sondele cu dublă cudură 9, 10 sau 17."},{"id":"D","text":"Prezintă o evoluție rapidă în profunzime și subgingival."},{"id":"E","text":"Se asociază la inspecție cu o papilă interdentară edemațiată și de culoare roșie - violacee."}],"correct":["B","C","D","E"],"pages":[40],"source":"set-2"},{"id":"set2-H4isZ2ns","fingerprint":"74e2aa1cdfdcccbd","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Ce topografii și direcții de evoluție pot prezenta cariile proximale de la nivelul dinților frontali?","options":[{"id":"A","text":"Leziune care întrerupe creasta marginală."},{"id":"B","text":"Leziune cu evoluție spre unghiul incizal."},{"id":"C","text":"Leziune incipientă pe mijlocul feței proximale."},{"id":"D","text":"Leziune cu evoluție vestibulară."},{"id":"E","text":"Leziune care interesează primar și evoluează exclusiv pe cementul radicular."}],"correct":["A","B","C","D"],"pages":[40],"source":"set-2"},{"id":"set2-DlYCG_pf","fingerprint":"eee16b312ac5e80a","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Ce metode paraclinice sau instrumentar se utilizează pentru confirmarea diagnosticului în cazul unei leziuni carioase incipiente localizate pe mijlocul feței proximale a unui dinte frontal?","options":[{"id":"A","text":"Palparea exclusivă cu sonda 17 fără metode de separare."},{"id":"B","text":"Separarea dinților cu separatorul Ivory."},{"id":"C","text":"Transiluminarea."},{"id":"D","text":"Decelarea papilei interdentare roșii-violacee."},{"id":"E","text":"Separarea dentară lentă timp de mai multe zile."}],"correct":["B","C"],"pages":[40],"source":"set-2"},{"id":"set2-CEKauFs5","fingerprint":"7dc8e94e6bb28e58","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele afirmații referitoare la caracteristicile leziunilor carioase situate pe suprafața radiculară sunt corecte?","options":[{"id":"A","text":"Forma cavitară medie are o adâncime mai mare de 0,5 mm, iar suprafața dentinei este moale la palpare."},{"id":"B","text":"Extinderea leziunilor active cavitare are loc mai mult orizontal decât vertical."},{"id":"C","text":"Forma cavitară superficială prezintă o adâncime mai mică de 0,5 mm, iar suprafața cementului este moale și neregulată."},{"id":"D","text":"Forma necavitară se caracterizează prin prezența unei suprafețe neregulate, de culoare maro-deschis sau închis."},{"id":"E","text":"Extinderea leziunilor active cavitare este mai mare în profunzime decât în suprafață."}],"correct":["A","B","C"],"pages":[41],"source":"set-2"},{"id":"set2-eMpH043T","fingerprint":"e7b7d7d0d2bd4254","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Un pacient prezintă pierdere de substanță dură dentară, însoțită de durere provocată de excitanți termici și chimici. Durerea persistă timp de 10-15 minute după îndepărtarea excitantului. Care este diagnosticul corespunzător acestui tablou clinic?","options":[{"id":"A","text":"Caria simplă"},{"id":"B","text":"Pulpita cronică închisă"},{"id":"C","text":"Hiperestezia dentinară"},{"id":"D","text":"Hiperemia preinflamatorie"},{"id":"E","text":"Gangrena pulpară"}],"correct":["D"],"pages":[42],"source":"set-2"},{"id":"set2-JiKGY_VH","fingerprint":"f5c46eb5ba9416e0","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Diagnosticul pozitiv de carie simplă se stabilește pe baza unor semne clinice specifice. Care dintre următoarele elemente sunt incluse în aceste criterii diagnostice?","options":[{"id":"A","text":"Durere spontană care iradiază în regiunile învecinate."},{"id":"B","text":"Camera pulpară închisă."},{"id":"C","text":"Percuție în ax și transversală pozitivă."},{"id":"D","text":"Teste de sensibilitate pulpară pozitive."},{"id":"E","text":"Sensibilitate la palpare cu sonda pe pereții juxtapulpari."}],"correct":["B","D","E"],"pages":[42],"source":"set-2"},{"id":"set2-QFnA7rI8","fingerprint":"7f72759698f949aa","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este o caracteristică specifică a leziunilor carioase situate în zona cervicală?","options":[{"id":"A","text":"Sunt leziuni asimptomatice chiar și în stadiile avansate de pierdere a substanței dure."},{"id":"B","text":"Nu pot evolua subgingival pentru a interesa cementul radicular."},{"id":"C","text":"Leziunile incipiente, necavitare se prezintă sub forma unor pete maronii, lucioase."},{"id":"D","text":"Prezintă o tendință de evoluție inițial în profunzime și ulterior în suprafață."},{"id":"E","text":"În cazul atrofiilor orizontale ale parodonțiului marginal, procesul carios interesează coletul dintelui de jur împrejur, formând carii circulare."}],"correct":["E"],"pages":[41],"source":"set-2"},{"id":"set2-U1kxD47C","fingerprint":"ea70ddb751c1b522","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Evoluția proceselor carioase netratate poate genera o serie de complicații imediate. Care dintre următoarele patologii se încadrează în această categorie?","options":[{"id":"A","text":"Edentațiile extinse cu tulburări fizionomice."},{"id":"B","text":"Focarele de infecție cu punct de plecare dentar."},{"id":"C","text":"Gangrena pulpară simplă."},{"id":"D","text":"Inflamațiile pulpare acute."},{"id":"E","text":"Inflamațiile pulpare cronice."}],"correct":["C","D","E"],"pages":[42],"source":"set-2"},{"id":"set2-6T3J7JUZ","fingerprint":"7248b8628a8717fc","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt semnele clinice pe baza cărora se stabilește diagnosticul pozitiv de carie secundară marginală?","options":[{"id":"A","text":"Culoarea normală a smalțului, asociată cu prezența factorului etiologic traumatic în anamneză."},{"id":"B","text":"Probele de sensibilitate pulpară negative."},{"id":"C","text":"Colorația alb-cretoasă sau brun-cafenie a smalțului de la marginea restaurării."},{"id":"D","text":"Prezența la palpare cu sonda în profunzime a dentinei necrotice."},{"id":"E","text":"Existența unei soluții de continuitate între restaurare și țesutul dentar dur la un dinte cu obturație coronară."}],"correct":["C","D","E"],"pages":[43],"source":"set-2"},{"id":"set2-zd3htyUY","fingerprint":"e6d1b8f742cc3564","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile care diferențiază fractura restaurării ocluzo-proximale la nivelul istmului de caria secundară marginală?","options":[{"id":"A","text":"Apare ca urmare a subminării smalțului de către procesul carios."},{"id":"B","text":"Este lipsită de prezența dentinei necrotice."},{"id":"C","text":"Apare la un interval scurt de timp de la aplicarea materialului de restaurare."},{"id":"D","text":"Este rezultatul unei preparări incorecte a cavității."},{"id":"E","text":"Se asociază cu prezența dentinei necrotice la nivelul defectului marginal."}],"correct":["B","C","D"],"pages":[44],"source":"set-2"},{"id":"set2-5NqJrPW0","fingerprint":"81c5e889693aa489","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt acuzele pacienților pe parcursul evoluției cariei secundare marginale?","options":[{"id":"A","text":"Dureri la masticație în zona laterală din cauza fracturării restaurării sau fisurilor."},{"id":"B","text":"Sensibilitate dureroasă extremă la palpare superficială, instalată încă din faza de debut."},{"id":"C","text":"Retenția de resturi alimentare la marginea restaurării."},{"id":"D","text":"Dureri provocate de excitanți chimici, care dispar după îndepărtarea acestora."},{"id":"E","text":"Dureri cu caracter spontan care iradiază în regiunile hemifeței."}],"correct":["A","C","D"],"pages":[43],"source":"set-2"},{"id":"set2-pj9W2Cv9","fingerprint":"bee31a3d79925655","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"În situația prezenței unor fisuri ale materialului de restaurare asociate cu o sensibilitate dureroasă neprecizată topografic, care este procedura clinică recomandată pentru localizarea dintelui cauzal?","options":[{"id":"A","text":"Se solicită pacientului să strângă dinții pe un rulou de vată foarte strâns sau pe un bețișor de lemn."},{"id":"B","text":"Se explorează șanțurile ocluzale cu o sondă rigidă până la apariția durerii."},{"id":"C","text":"Se realizează teste de sensibilitate termică la toți dinții de pe hemiarcada respectivă."},{"id":"D","text":"Se îndepărtează în totalitate obturația suspectă pentru a inspecta pereții preparației."},{"id":"E","text":"Se aplică excitanți chimici la baza papilei interdentare."}],"correct":["A"],"pages":[43],"source":"set-2"},{"id":"set2-V22mYamw","fingerprint":"55d6d0e209f9d97a","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt direcțiile de evoluție și complicațiile posibile ale unei carii secundare marginale netratate?","options":[{"id":"A","text":"Extinderea către suprafață cu fracturarea marginilor preparației sau a dintelui."},{"id":"B","text":"Producerea unei pierderi superficiale de material restaurator prin adaptare incorectă."},{"id":"C","text":"Evoluția spre profunzime determinând infectarea pulpei."},{"id":"D","text":"Remineralizarea spontană a dentinei subiacente prin depunere de dentină de iritație."},{"id":"E","text":"Declanșarea gangrenei pulpare ca urmare a avansării procesului carios."}],"correct":["A","C","E"],"pages":[44],"source":"set-2"},{"id":"set2-xOrKn2ze","fingerprint":"2d08ca3006139fef","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este afirmația ce descrie manifestările clinice ale recidivei de carie?","options":[{"id":"A","text":"Afecțiunea debutează cu o simptomatologie intensă, fiind ușor de diagnosticat în stadiile precoce."},{"id":"B","text":"Îndepărtarea dentinei necrotice este permanent însoțită de o sensibilitate dureroasă extremă, chiar și în caz de gangrenă pulpară."},{"id":"C","text":"Durerea este provocată de excitanți fizici sau chimici, fiind similară cu cea din caria simplă sau inflamațiile pulpare acute."},{"id":"D","text":"Evoluția spre suprafața dintelui asociază întotdeauna o zonă de retenție între pereții dentari și materialul restaurator."},{"id":"E","text":"Dentina necrotică se formează exclusiv pe peretele pulpar al cavității."}],"correct":["C"],"pages":[44],"source":"set-2"},{"id":"set2-49AgqM-1","fingerprint":"3d0bfc3f74509bd2","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt semnele clinice pe baza cărora se stabilește diagnosticul pozitiv de recidivă de carie?","options":[{"id":"A","text":"Apariția semnelor clinice caracteristice cariei simple sau complicațiilor pulpare acute"},{"id":"B","text":"Prezența unui dinte cu o restaurare coronară bine adaptată marginal"},{"id":"C","text":"Identificarea dentinei necrotice la îndepărtarea restaurării"},{"id":"D","text":"Absența dentinei necrotice și prezența camerei pulpare închise la îndepărtarea materialului restaurator"},{"id":"E","text":"Identificarea unei soluții de discontinuitate marginală la interfața dintre dinte și restaurare"}],"correct":["A","B","C"],"pages":[44],"source":"set-2"},{"id":"set2--PmcxAzL","fingerprint":"9f9fa5e45f7b2804","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile necrozei pulpare utilizate în diagnosticul diferențial al recidivei de carie?","options":[{"id":"A","text":"Menținerea culorii normale a țesuturilor dure dentare"},{"id":"B","text":"Lipsa sensibilității dureroase la testele de sensibilitate pulpară"},{"id":"C","text":"Prezența dentinei necrotice abundente la îndepărtarea restaurării coronare"},{"id":"D","text":"Camera pulpară se prezintă închisă la îndepărtarea restaurării"},{"id":"E","text":"Restaurarea coronară este corect adaptată"}],"correct":["B","D","E"],"pages":[44],"source":"set-2"},{"id":"set2-qWZ4vs5Q","fingerprint":"acf0a0987a31021d","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt direcțiile de evoluție și complicațiile asociate recidivei de carie?","options":[{"id":"A","text":"Apariția unei inflamații pulpare acute"},{"id":"B","text":"Formarea unei zone de retenție între pereții dentari și restaurare"},{"id":"C","text":"Instalarea gangrenei pulpare în lipsa tratamentului"},{"id":"D","text":"Evoluția procesului carios se realizează predominant spre camera pulpară"},{"id":"E","text":"Fracturarea unor pereți dentari prin subminarea țesuturilor dure"}],"correct":["A","C","D","E"],"pages":[44],"source":"set-2"},{"id":"set2-IeEbuHvl","fingerprint":"c1f36f4ddfda777f","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"În cadrul diagnosticului diferențial al recidivei de carie, care afirmație descrie caracteristicile gangrenei pulpare?","options":[{"id":"A","text":"La îndepărtarea restaurării coronare se observă dentina necrotică și camera pulpară deschisă, cu lipsa vitalității țesutului pulpar."},{"id":"B","text":"Restaurarea coronară este incorect adaptată, iar culoarea țesuturilor dure dentare rămâne nemodificată."},{"id":"C","text":"Se evidențiază o soluție de discontinuitate marginală la interfața dinte/restaurare."},{"id":"D","text":"Simptomatologia algică este intensă, similară exclusiv inflamației pulpare acute."},{"id":"E","text":"Camera pulpară este închisă și nu apare dentină necrotică după îndepărtarea materialului restaurator."}],"correct":["A"],"pages":[44],"source":"set-2"},{"id":"set2-Stq2nGkD","fingerprint":"78088b400c2b1790","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt criteriile pe care se bazează sistemul ICDAS pentru depistarea leziunilor carioase în funcție de stadiul lor de evoluție?","options":[{"id":"A","text":"Determinarea nivelului de colonizare bacteriană de la nivelul plăcii dentare"},{"id":"B","text":"Topografia dinților, incluzând fosete, șanțuri sau suprafețe netede"},{"id":"C","text":"Evaluarea obiectivă a sensibilității pulpare la excitanți fizici și chimici"},{"id":"D","text":"Partea anatomică evaluată, cu referire la coroană și rădăcină"},{"id":"E","text":"Evaluarea prezenței și a gradului de afectare a unei suprafețe adiacente unei sigilări sau restaurări"}],"correct":["B","D","E"],"pages":[45],"source":"set-2"},{"id":"set2-H8B-eGRl","fingerprint":"8f2cd122ce5d270f","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele asocieri referitoare la codurile de detectare a leziunilor carioase și gradul lor de severitate sunt descrise cu acuratețe?","options":[{"id":"A","text":"Codul 1 semnifică prima modificare vizibilă la nivelul smalțului"},{"id":"B","text":"Codul 4 presupune o modificare de culoare, care apare sub formă de umbră sau halou întunecat, provenită de la nivel dentinar"},{"id":"C","text":"Codul 5 implică o leziune cavitară extinsă, asociată cu o afectare severă și profundă a camerei pulpare"},{"id":"D","text":"Codul 6 reprezintă stadiul manifestat printr-o leziune cavitară extinsă, asociată cu o afectare vizibilă a dentinei"},{"id":"E","text":"Codul 3 descrie o distrucție localizată la nivelul smalțului însoțită de semne clinice vizibile de afectare dentinară"}],"correct":["A","B","D"],"pages":[45],"source":"set-2"},{"id":"set2-XzeInq-_","fingerprint":"d653270250cff0b8","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este principalul motiv ce a condus la conceperea și implementarea sistemului internațional de detecție și evaluare a cariilor?","options":[{"id":"A","text":"Standardizarea exclusivă a protocoalelor chirurgicale pentru leziunile extinse"},{"id":"B","text":"Necesitatea unui concept standardizat, susținut de valori bazate pe dovezi și obiectivate prin studii pentru diagnostic, prognostic și profilaxie"},{"id":"C","text":"Introducerea unei metode care evaluează cariile radiculare doar la pacienții în vârstă"},{"id":"D","text":"Eliminarea completă a tehnicilor radiologice clasice din procesul de diagnosticare clinică"},{"id":"E","text":"Crearea unui algoritm bazat strict pe topografia fisurilor și șanțurilor de la nivelul molarilor de minte"}],"correct":["B"],"pages":[45],"source":"set-2"},{"id":"set2-xbSk414A","fingerprint":"064a0ed4f8c41d8b","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele stadii de severitate sunt caracterizate prin prezența unei afectări vizibile a dentinei asociate unei leziuni cavitare?","options":[{"id":"A","text":"Codul 3"},{"id":"B","text":"Codul 5"},{"id":"C","text":"Codul 2"},{"id":"D","text":"Codul 4"},{"id":"E","text":"Codul 6"}],"correct":["B","E"],"pages":[45],"source":"set-2"},{"id":"set2-vYEYWMEU","fingerprint":"34fda92353b6907d","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele aspecte clinice se înregistrează cu Codul 0 (suprafață dentară sănătoasă) în evaluarea șanțurilor și fosetelor?","options":[{"id":"A","text":"Umbra de dentină colorată vizibilă prin transparența smalțului aparent intact"},{"id":"B","text":"Uzura dentară manifestată prin eroziune sau abraziune"},{"id":"C","text":"Opacitatea carioasă vizibilă exclusiv după o uscare prelungită de 5 secunde"},{"id":"D","text":"Modificările de culoare datorate fluorozei"},{"id":"E","text":"Hipoplaziile de smalț"}],"correct":["B","D","E"],"pages":[45],"source":"set-2"},{"id":"set2-WuKbl3Pb","fingerprint":"1e961717e4e8e7cf","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este caracteristica definitorie a unei leziuni carioase în șanțuri și fosete evaluate cu Codul 4?","options":[{"id":"A","text":"Pierderea evidentă clinic a structurii dentare la nivelul intrării în fisură, cu o cavitate clară și expunerea dentinei subiacente"},{"id":"B","text":"Distrucția localizată exclusiv în smalț, fără expunerea dentinei și fără prezența haloului de la nivel dentinar"},{"id":"C","text":"Opacitatea carioasă care devine vizibilă doar după o uscare prelungită de 5 secunde, pe o suprafață aparent nemodificată când este umedă"},{"id":"D","text":"Cavitatea profundă și extinsă cu dentină vizibilă pe podea și pe pereții laterali"},{"id":"E","text":"Prezența unei umbre ușoare de dentină colorată (halou întunecat), vizibilă prin transparența smalțului aparent intact"}],"correct":["E"],"pages":[45],"source":"set-2"},{"id":"set2-_fDvNhyc","fingerprint":"05def348907ffb42","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Prin ce se caracterizează leziunile carioase de la nivelul șanțurilor și fosetelor încadrate la Codul 1?","options":[{"id":"A","text":"Absența oricărei modificări de culoare atribuibile unei leziuni carioase atunci când suprafața dentară este umedă"},{"id":"B","text":"Existența unei distrucții localizate în smalț însoțite de pierderea structurii dentare la intrarea în fosetă"},{"id":"C","text":"Prezența unei modificări de culoare localizate la întâlnirea dintre șanțuri și fosete, vizibilă indiferent dacă suprafața este umedă sau uscată"},{"id":"D","text":"Apariția unei opacități carioase sau a unei modificări de culoare de tip white-spot sau brown-spot după o uscare prelungită de 5 secunde"},{"id":"E","text":"Observarea, pe dintele umed, a unei colorații maronii mai extinse decât limitele anatomice ale șanțurilor și fosetelor"}],"correct":["A","C","D"],"pages":[45],"source":"set-2"},{"id":"set2-s3-Kf1qT","fingerprint":"cddcc12c8fba88ec","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Un dinte prezintă, în stare umedă, opacități și colorații maronii mai extinse decât șanțurile și fosetele. După o uscare de 5 secunde se observă o pierdere a structurii dentare la intrarea în șanț, fără expunerea dentinei și fără prezența unui halou dentinar. Cărui stadiu diagnostic îi corespunde acest tablou clinic?","options":[{"id":"A","text":"Cod 2"},{"id":"B","text":"Cod 4"},{"id":"C","text":"Cod 5"},{"id":"D","text":"Cod 1"},{"id":"E","text":"Cod 3"}],"correct":["E"],"pages":[45],"source":"set-2"},{"id":"set2-fE6CvMgy","fingerprint":"19a066aed43d8cc9","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt afirmațiile adevărate privind leziunile carioase încadrate la Codul 5 și Codul 6 la nivelul șanțurilor și fosetelor?","options":[{"id":"A","text":"Ambele coduri se definesc prin absența oricărei expuneri dentinare, procesul destructiv limitându-se la structura smalțului"},{"id":"B","text":"Codul 6 este caracterizat de o cavitate profundă și extinsă, prezentând dentină vizibilă atât pe podea, cât și pe pereții laterali ai cavității"},{"id":"C","text":"La nivelul Codului 5, în urma unei uscări de 5 secunde, devine vizibilă o cavitate clară, împreună cu o pierdere evidentă clinic a structurii dentare la intrarea în șanț"},{"id":"D","text":"Codul 5 se definește prin prezența unei leziuni cavitare în smalțul opac sau colorat, cu expunerea certă a dentinei subiacente"},{"id":"E","text":"Codul 6 se manifestă exclusiv sub forma unui halou întunecat vizibil prin smalțul aparent intact, fără existența unei cavități propriu-zise"}],"correct":["B","C","D"],"pages":[45],"source":"set-2"},{"id":"set2-S7l55llG","fingerprint":"5e57df9a3a82a850","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care dintre următoarele caracteristici clinice definește o leziune carioasă proximală încadrată la Codul 1 în sistemul ICDAS?","options":[{"id":"A","text":"O pierdere a integrității suprafeței smalțului observabilă exclusiv pe dintele umed."},{"id":"B","text":"O modificare vizuală distinctă a smalțului umed, având un aspect de umbră la nivelul crestei marginale."},{"id":"C","text":"O opacitate carioasă vizibilă exclusiv pe dintele umed, concordantă cu smalțul sănătos."},{"id":"D","text":"O umbră a dentinei pigmentate vizibilă prin creasta marginală intactă."},{"id":"E","text":"O opacitate carioasă neconcordantă cu aparența clinică a smalțului sănătos, vizibilă abia după uscarea intensă timp de 5 secunde."}],"correct":["E"],"pages":[46],"source":"set-2"},{"id":"set2-5GG2_1kS","fingerprint":"94e20e789184c6e8","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele afecțiunile sau modificările dentare sunt înregistrate cu Codul 0 (suprafață dentară sănătoasă) în sistemul de codificare ICDAS pentru suprafețele proximale?","options":[{"id":"A","text":"Fluoroza"},{"id":"B","text":"Eroziunea dentară"},{"id":"C","text":"Pierderea integrității suprafeței smalțului fără dentină vizibilă"},{"id":"D","text":"Colorațiile extrinseci sau intrinseci"},{"id":"E","text":"Hipoplazia de smalț"}],"correct":["A","B","D","E"],"pages":[46],"source":"set-2"},{"id":"set2-uLLOOKke","fingerprint":"5a69b8156565f051","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Cum se descrie clinic leziunea carioasă proximală corespunzătoare Codului 4 din sistemul ICDAS?","options":[{"id":"A","text":"O cavitate evidentă în smalțul colorat, cu dentină expusă vizibilă direct."},{"id":"B","text":"O umbră întunecată a dentinei subiacente, intrinsecă, vizibilă pe dintele umed prin creasta marginală intactă sau peretele de smalț."},{"id":"C","text":"O pierdere a integrității suprafeței smalțului observată dinspre oral sau vestibular, fără dentină vizibilă."},{"id":"D","text":"O opacitate carioasă vizibilă exclusiv după o uscare intensă a dintelui timp de 5 secunde."},{"id":"E","text":"O pierdere evidentă de structură dentară cu o cavitate extinsă ce implică cel puțin jumătate din suprafața dentară."}],"correct":["B"],"pages":[46],"source":"set-2"},{"id":"set2-wZEXg7Be","fingerprint":"457f25f076430df6","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile clinice ale unei leziuni carioase proximale evaluate cu Codul 6 în sistemul de codificare ICDAS?","options":[{"id":"A","text":"Posibila afectare a pulpei coronare."},{"id":"B","text":"Umbra întunecată a dentinei este vizibilă prin creasta marginală intactă, fără pierderea integrității smalțului."},{"id":"C","text":"Prezența unei cavități profunde cu dentină vizibilă atât pe pereți cât și la nivelul bazei acesteia."},{"id":"D","text":"Cavitatea extinsă implică cel puțin o jumătate din suprafața dentară."},{"id":"E","text":"Confirmarea diagnosticului necesită o uscare intensă timp de 5 secunde pentru vizualizarea unei opacități fără pierdere de structură."}],"correct":["A","C","D"],"pages":[46],"source":"set-2"},{"id":"set2-SHSPWrbP","fingerprint":"d3c790f5ec6ad90d","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este aspectul clinic caracteristic pentru leziunea carioasă de pe suprafețele netede clasificată drept Codul 1 în sistemul ICDAS?","options":[{"id":"A","text":"Există o opacitate vizibilă pe suprafața dintelui umed, localizată în apropierea marginii gingivale."},{"id":"B","text":"Se observă o pierdere distinctă a integrității smalțului, fără expunerea dentinei."},{"id":"C","text":"Leziunea apare sub forma unei umbre dentinare vizibile prin suprafața smalțului intact."},{"id":"D","text":"La examinarea dintelui umed nu se observă diferențe de culoare, opacitatea apărând exclusiv după uscarea prelungită cu aer."},{"id":"E","text":"Prezența unei cavități cu expunerea evidentă a dentinei subiacente."}],"correct":["D"],"pages":[46],"source":"set-2"},{"id":"set2-hmE9Dzmc","fingerprint":"c0c75f77055910f5","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele caracteristici descriu stadiile avansate ale leziunilor carioase pe suprafețele netede, corespunzătoare Codurilor 4, 5 și 6 din sistemul ICDAS?","options":[{"id":"A","text":"Codul 5 reprezintă prezența unei cavități cu expunerea dentinei."},{"id":"B","text":"Codul 4 se manifestă sub forma unei umbre sau discolorații dentinare vizibile prin suprafața smalțului, cu sau fără distrucția acestuia."},{"id":"C","text":"Codul 5 este definit de pierderea integrității smalțului strict fără expunerea dentinei."},{"id":"D","text":"Codul 6 corespunde unei cavități profunde cu extindere în suprafață și dentină vizibilă."},{"id":"E","text":"Codul 6 se caracterizează printr-o opacitate observabilă doar după uscarea prelungită cu aer."}],"correct":["A","B","D"],"pages":[46],"source":"set-2"},{"id":"set2-ef_WZHVS","fingerprint":"06eb5f611afb1a3a","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Ce criterii clinice sunt specifice leziunilor carioase de pe suprafețele netede în stadiile clasificate ca fiind Codul 2 și Codul 3 în sistemul ICDAS?","options":[{"id":"A","text":"Codul 3 asociază pierderea integrității smalțului cu expunerea vizibilă și profundă a dentinei."},{"id":"B","text":"Codul 2 descrie o suprafață dentară sănătoasă, fără semne clinice evidente de carie."},{"id":"C","text":"Codul 2 implică o modificare de culoare la nivelul dentinei vizibilă sub forma unei umbre."},{"id":"D","text":"Codul 3 presupune o pierdere distinctă a integrității smalțului, fără expunerea dentinei."},{"id":"E","text":"Codul 2 se caracterizează printr-o opacitate sau colorație localizată în apropierea marginii gingivale."}],"correct":["D","E"],"pages":[46],"source":"set-2"},{"id":"set2-e9-x2tm4","fingerprint":"faa29c5a476efb25","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este caracteristica principală a unei leziuni carioase asociate unei restaurări clasificată drept Cod 1?","options":[{"id":"A","text":"Reprezintă o cavitate cu lipsă de substanță dură dentară mai mare de 0,5 mm."},{"id":"B","text":"O opacitate sau colorație consecutivă demineralizării devine vizibilă exclusiv după uscarea prelungită cu aer."},{"id":"C","text":"Prezintă dentină necrotică subiacentă vizibilă printr-o suprafață de smalț aparent integră."},{"id":"D","text":"Nu se înregistrează nicio modificare a translucidității smalțului după uscare timp de 5 secunde."},{"id":"E","text":"Este vizibilă o zonă opacă sau o colorație distinctă direct pe dintele umed."}],"correct":["B"],"pages":[46],"source":"set-2"},{"id":"set2-dJx1OP-E","fingerprint":"9afde5cc38658872","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt criteriile de diagnostic pentru o leziune carioasă asociată unei restaurări sau sigilări clasificată cu codul 5?","options":[{"id":"A","text":"Existența unei discontinuități evidente la nivelul marginilor restaurării detectabilă cu vârful unei sonde de 0,5 mm, atunci când marginile nu sunt direct vizibile."},{"id":"B","text":"Prezența unei cavități extinse în profunzime, cu dentină vizibilă inclusiv la nivelul peretelui pulpar sau parapulpar."},{"id":"C","text":"Dimensiunea leziunii este mai mică de 0,5 mm, suprafața prezentând o umbră determinată de culoarea dentinei."},{"id":"D","text":"Distrucția limitată a smalțului, fără dentină vizibilă, dar cu prezența unei carii marginale."},{"id":"E","text":"Expunerea dentinei însoțită de o lipsă de substanță dură dentară mai mare de 0,5 mm."}],"correct":["A","E"],"pages":[47],"source":"set-2"},{"id":"set2-FIm4CZCC","fingerprint":"cf0c537f96812cb5","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt trăsăturile clinice definitorii pentru leziunile carioase adiacente restaurărilor încadrate în codul 3?","options":[{"id":"A","text":"Defectul dentar implică o lipsă de substanță dură dentară mai mare de 0,5 mm."},{"id":"B","text":"Leziunea se prezintă sub forma unei umbre determinate de culoarea dentinei subiacente."},{"id":"C","text":"Se constată prezența unei suprafețe opace sau a unor colorații, alături de modificarea suprafeței smalțului."},{"id":"D","text":"Dimensiunea leziunii carioase este strict mai mică de 0,5 mm în smalț, dentină sau cement."},{"id":"E","text":"Se remarcă o cavitație evidentă în care dentina este vizibilă la nivelul pereților laterali și al planșeului pulpar."}],"correct":["B","C","D"],"pages":[47],"source":"set-2"},{"id":"set2-XSrl2o5L","fingerprint":"f0da9ea47ca98a23","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este elementul descriptiv esențial pentru o leziune carioasă asociată unei restaurări clasificată cu codul 6?","options":[{"id":"A","text":"Existența unei leziuni cu o lipsă de substanță limitată strict la o dimensiune mai mică de 0,5 mm."},{"id":"B","text":"Identificarea unei discontinuități evidente la nivelul marginilor restaurării folosind o sondă de 0,5 mm."},{"id":"C","text":"Modificarea vizuală distinctă sub formă de zonă opacă observabilă exclusiv pe dintele umed, în absența oricărei lipse de substanță."},{"id":"D","text":"Prezența dentinei necrotice subiacente vizibile exclusiv printr-o suprafață de smalț aparent integră."},{"id":"E","text":"Vizibilitatea dentinei atât pe pereții cavității extinse, cât și la nivelul peretelui pulpar sau parapulpar."}],"correct":["E"],"pages":[47],"source":"set-2"},{"id":"set2-j_TUkRUM","fingerprint":"a3e4afaf11ceef5c","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele afirmații descriu stadiile incipiente de diagnostic (codurile 0, 1 și 2) ale suprafețelor dentare adiacente restaurărilor și sigilărilor?","options":[{"id":"A","text":"Codul 2 impune existența obligatorie a unei umbre generate de culoarea dentinei subiacente la o leziune mai mică de 0,5 mm."},{"id":"B","text":"Codul 0 indică o suprafață dentară la care nu se observă nicio modificare a translucidității smalțului după uscare timp de 5 secunde."},{"id":"C","text":"Codul 1 este definit prin prezența unei distrucții limitate a smalțului cu afectare marginală, fără a expune dentina."},{"id":"D","text":"Codul 2 se caracterizează printr-o modificare vizuală distinctă sub formă de zonă opacă sau colorație vizibilă la examinarea pe dintele umed."},{"id":"E","text":"Codul 1 presupune absența oricărei dovezi de modificare a culorii pe suprafața umedă, opacitatea apărând doar consecutiv uscării prelungite."}],"correct":["B","D","E"],"pages":[46],"source":"set-2"},{"id":"set2-MrTW9Kzy","fingerprint":"8173fd7251802a9f","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile anatomiei radiologice ale structurilor dentare coronare?","options":[{"id":"A","text":"Camera pulpară este o porțiune de radiotransparență cu o tentă cenușiu închisă, situată în centrul coroanei."},{"id":"B","text":"Smalțul se îngroașă progresiv spre joncțiunea cu cementul, având un aspect rotunjit."},{"id":"C","text":"Imaginea radiologică normală a structurilor coronare este catalogată drept stadiul II în indexul radiologic pentru carii proximale."},{"id":"D","text":"Smalțul coronar se prezintă ca zona cu cea mai mare radioopacitate."},{"id":"E","text":"Dentina coronară apare ca fiind zona din interiorul smalțului cu o nuanță de alb mai puțin intensă."}],"correct":["A","D","E"],"pages":[47],"source":"set-2"},{"id":"set2-TbnDOGK6","fingerprint":"1760f393bca85f51","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este gradul minim de demineralizare necesar pentru ca o leziune carioasă să poată fi vizibilă pe o imagine radiologică?","options":[{"id":"A","text":"Minim 50% pentru senzorii clasici și minim 25-30% pentru senzorii digitali."},{"id":"B","text":"Minim 20% pentru senzorii clasici și minim 1-5% pentru senzorii digitali."},{"id":"C","text":"Minim 30% pentru senzorii clasici și minim 5-10% pentru senzorii digitali."},{"id":"D","text":"Minim 40% pentru senzorii clasici și minim 15-20% pentru senzorii digitali."},{"id":"E","text":"Minim 5-10% pentru senzorii clasici și minim 30% pentru senzorii digitali."}],"correct":["C"],"pages":[48],"source":"set-2"},{"id":"set2-QeUvYsjw","fingerprint":"95445ea3b4e51a43","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt factorii care influențează capacitatea de detecție a leziunilor carioase pe imaginile radiologice?","options":[{"id":"A","text":"Cantitatea de radiații absorbite de materialele de obturație vecine."},{"id":"B","text":"Subiectivismul și gradul de pregătire al examinatorului."},{"id":"C","text":"Condițiile de examinare."},{"id":"D","text":"Calitatea imaginii radiologice."},{"id":"E","text":"Viteza de formare a dentinei secundare."}],"correct":["B","C","D"],"pages":[48],"source":"set-2"},{"id":"set2-bNVZ7wPS","fingerprint":"f92cc3b92950f7a9","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele aspecte descriu noțiunile elementare de semiologie radiologică aplicabile în diagnosticul cariei simple cavitare?","options":[{"id":"A","text":"Zonele anatomic mai puțin dense generează o intensitate radiologică redusă, numită radiotransparență."},{"id":"B","text":"Radiotransparența se manifestă pe radiografie prin nuanțe variate de gri deschis spre alb."},{"id":"C","text":"Modificările de contur ale imaginii exclud posibilitatea existenței unor contururi șterse."},{"id":"D","text":"Modificările de omogenitate ale imaginii sunt reprezentate de zone cu intensitate radiologică uniformă și/sau neuniformă."},{"id":"E","text":"Zonele anatomic mai dense generează o intensitate radiologică crescută, cunoscută sub denumirea de radioopacitate."}],"correct":["A","D","E"],"pages":[47],"source":"set-2"},{"id":"set2-CN_bonMr","fingerprint":"47888708e4ae8996","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Obținerea radiografiilor este posibilă pe baza căror caracteristici ale radiațiilor Röntgen utilizate?","options":[{"id":"A","text":"Absorbția variabilă de către țesuturi care conțin structuri cu densitate anatomică diferită."},{"id":"B","text":"Penetrabilitatea acestora prin țesuturi."},{"id":"C","text":"Ionizarea constantă și uniformă a suprafeței senzorului, indiferent de țesuturile traversate."},{"id":"D","text":"Transformarea imaginii tridimensionale într-o reprezentare grafică holografică."},{"id":"E","text":"Ionizarea variabilă a suprafeței senzorului corespunzător țesuturilor traversate."}],"correct":["A","B","E"],"pages":[47],"source":"set-2"},{"id":"set2-HysXcf4f","fingerprint":"31bbd11dffbc8deb","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Care este aspectul radiologic caracteristic cariei proximale în smalț și dentină, cu extindere externă (stadiul avansat sau stadiul III)?","options":[{"id":"A","text":"Prezența a două triunghiuri radiotransparente, unul localizat în smalț și celălalt, mai extins, în dentină."},{"id":"B","text":"Radiotransparență de formă aproximativ semilunară, extinsă strict în jumătatea externă a grosimii smalțului."},{"id":"C","text":"Radiotransparență triunghiulară cu baza largă spre suprafața dintelui, extinsă exclusiv în jumătatea internă a grosimii smalțului."},{"id":"D","text":"Radiotransparență de profunzime variabilă situată imediat sub limita apicală a smalțului, prezentând frecvent fenomenul de burn-out."},{"id":"E","text":"O radiotransparență mare cu forme atipice, extinsă în jumătatea internă a dentinei, prin pierderea individualității imaginii bipolare."}],"correct":["A"],"pages":[48],"source":"set-2"},{"id":"set2-1Nt0-r8n","fingerprint":"271e5103cd8e8a98","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la aspectul radiologic al leziunilor carioase simple de la nivelul coletului?","options":[{"id":"A","text":"Fenomenul de ardere radiologică reprezintă o zonă de radioopacitate intensă la nivelul joncțiunii smalț-cement."},{"id":"B","text":"Inițial, se prezintă sub forma unor imagini de farfurie, datorită extinderii în suprafață și profunzimii reduse."},{"id":"C","text":"În stadiile avansate, radiotransparența este situată imediat deasupra limitei apicale a smalțului."},{"id":"D","text":"Diagnosticul poate fi îngreunat de prezența fenomenului de ardere radiologică (burn-out)."},{"id":"E","text":"Fenomenul de ardere radiologică poate fi sursa unor diagnostice false de carie simplă cervicală."}],"correct":["B","D","E"],"pages":[48],"source":"set-2"},{"id":"set2-ShGidOGu","fingerprint":"0f36989681e4d0ec","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care dintre următoarele afirmații referitoare la diagnosticul radiologic al proceselor carioase sunt adevărate?","options":[{"id":"A","text":"Cariile simple ale fețelor vestibulare sau orale devin radiologic evidente doar în stadiile în care există o interesare mare a dentinei."},{"id":"B","text":"Caria ocluzală extinsă în dentină se prezintă ca o radiotransparență mărginită de camera pulpară, cu contururi extinse spre joncțiunea smalț-dentină."},{"id":"C","text":"Recidiva de carie apare ca o zonă radiotransparentă de dimensiuni mici, cu limită netă spre materialul de obturație și limită ștearsă spre dentină."},{"id":"D","text":"Caria secundară marginală prezintă radiotransparențe situate la marginea obturației, cu contururi nete spre material și șterse în rest."},{"id":"E","text":"Caria ocluzală limitată la smalț permite un radiodiagnostic precoce facil datorită vizibilității nete prin grosimea cuspizilor."}],"correct":["A","C","D"],"pages":[48],"source":"set-2"},{"id":"set2-WHWBYoU3","fingerprint":"c5ebc28b87968d16","chapterId":"set-2","subchapterId":"set2-1.04","type":"CM","text":"Care sunt caracteristicile imaginilor radiologice ale materialelor utilizate pentru restaurarea coronară?","options":[{"id":"A","text":"Obturațiile realizate cu materiale aderente radioopace prezintă o radioopacitate mai intensă comparativ cu cea a amalgamului dentar."},{"id":"B","text":"Materialele radioopace utilizate ca obturații de bază prezintă o radioopacitate intensă care urmărește conturul cavităților neretentive."},{"id":"C","text":"Obturațiile de durată din amalgam prezintă o radioopacitate intensă cu contururi nete, caracteristice geometriei cavităților retentive."},{"id":"D","text":"Materialele compozite radiotransparente utilizate pentru obturații de durată oferă o imagine de radioopacitate moderată, specifică geometriei cavităților neretentive."},{"id":"E","text":"Materialele aderente radioopace conturează cavități retentive, având o radioopacitate intensă similară cu a amalgamului."}],"correct":["B","C","D"],"pages":[49],"source":"set-2"},{"id":"set2-kQ8LLsJi","fingerprint":"162275cf1d15f6cf","chapterId":"set-2","subchapterId":"set2-1.04","type":"CS","text":"Cum este descrisă imaginea internă a cariei proximale limitate la smalț (stadiul moderat sau stadiul II)?","options":[{"id":"A","text":"O radiotransparență triunghiulară cu unghiuri rotunjite, având baza largă spre suprafața dintelui și vârful spre joncțiunea smalț-dentină."},{"id":"B","text":"O radiotransparență difuză, cu forme atipice, situată în jumătatea internă a dentinei, în proximitatea camerei pulpare."},{"id":"C","text":"O radiotransparență triunghiulară cu baza spre joncțiunea smalț-dentină și vârful spre camera pulpară."},{"id":"D","text":"O radiotransparență de formă semilunară, cu porțiunea bombată orientată spre suprafața dintelui."},{"id":"E","text":"O imagine bipolară formată din două triunghiuri radiotransparente extinse atât în smalț, cât și în dentină."}],"correct":["A"],"pages":[48],"source":"set-2"}];
